import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useGame } from '../context/GameContext';
import { DIALOGUES, CHARACTERS, ENEMY_GROUPS, CGS, MAPS, ITEMS, QUESTS } from '../data';

export default function DialogueView() {
  const { state, dispatch } = useGame();
  const dialogue = DIALOGUES[state.currentDialogue];
  const [displayedText, setDisplayedText] = useState('');
  const [textComplete, setTextComplete] = useState(false);
  const [showChoices, setShowChoices] = useState(false);
  const [cgActive, setCgActive] = useState(false);
  const typewriterSpeed = 25;
  const typewriterIntervalRef = useRef(null);
  const cgTimeoutRef = useRef(null);

  const prevQuestsRef = useRef(state.quests);

  // ---------- helpers ----------

  const buildBattleParty = useCallback(() =>
    state.activeLineup.map(cId => {
      const char = CHARACTERS[cId];
      const status = state.characterStatus[cId] || {};
      const asc = state.characterAscension[cId] || 0;
      const allSkills = [...char.skills];
      if (asc >= 1 && char.skill2) allSkills.push(char.skill2);
      const maxHp = status.baseHp || char.stats.hp;
      const maxMp = status.baseMp || char.stats.mp;
      return {
        ...char,
        skills: allSkills,
        battleId: cId,
        currentHp: status.currentHp ?? maxHp,
        currentMp: status.currentMp ?? maxMp,
        stats: {
          ...char.stats,
          hp: maxHp,
          maxHp,
          mp: maxMp,
          maxMp,
          atk: status.atk || char.stats.atk,
          def: status.def || char.stats.def,
          spd: status.spd || char.stats.spd,
          mag: status.mag || char.stats.mag,
        },
      };
    }),
  [state.activeLineup, state.characterStatus, state.characterAscension]);

  const dispatchBattle = useCallback((groupId, returnDialogue) => {
    const group = ENEMY_GROUPS[groupId];
    if (!group) return;
    const enemies = group.enemies.map((eId, i) => ({
      ...CHARACTERS[eId],
      battleId: `${eId}_${i}_${Date.now()}`,
      currentHp: CHARACTERS[eId].stats.hp,
      currentMp: CHARACTERS[eId].stats.mp,
    }));
    dispatch({
      type: 'SET_BATTLE_STATE',
      payload: {
        enemyGroupId: groupId,
        enemies,
        party: buildBattleParty(),
        turnOrder: [],
        currentTurnIndex: 0,
        phase: 'player_turn',
        selectedAction: null,
        battleLog: ['⚔️ Battle started!'],
        goldReward: group.goldReward,
        itemRewards: group.itemRewards,
        expReward: group.expReward,
        returnDialogue: returnDialogue || null,
      },
    });
  }, [dispatch, buildBattleParty]);

  // ---------- advance dialogue ----------

  const advanceDialogue = useCallback(() => {
    // Step 1: finish typewriter if still running
    if (!textComplete) {
      if (typewriterIntervalRef.current) {
        clearInterval(typewriterIntervalRef.current);
        typewriterIntervalRef.current = null;
      }
      setDisplayedText(dialogue.text);
      setTextComplete(true);
      if (dialogue.choices?.length) {
        setTimeout(() => setShowChoices(true), 200);
      }
      return;
    }

    // Step 2: show choices if not yet shown
    if (dialogue.choices?.length && !showChoices) {
      setShowChoices(true);
      return;
    }

    // FIX: apply effects BEFORE dispatching transitions so time/gold are correct
    if (dialogue.effects) {
      // Gold guard
      if (dialogue.effects.gold && state.gold + dialogue.effects.gold < 0) {
        alert('Not enough gold!');
        return;
      }
      // Notify newly accepted quests
      if (dialogue.effects.quests) {
        Object.entries(dialogue.effects.quests).forEach(([questId, status]) => {
          if (status === 'active' && state.quests[questId]?.status !== 'active') {
            const quest = QUESTS[questId];
            if (quest) {
              dispatch({
                type: 'SHOW_NOTIFICATION',
                payload: { message: `📜 Quest accepted: ${quest.name}` },
              });
            }
          }
        });
      }
      // startMinigame in effects — dispatch it then stop; don't fall through
      if (dialogue.effects.startMinigame) {
        dispatch({ type: 'ADVANCE_TIME', payload: 5 });
        dispatch({ type: 'START_MINIGAME', payload: dialogue.effects.startMinigame });
        return;
      }
      dispatch({ type: 'APPLY_EFFECTS', payload: dialogue.effects });
      // If effects contain a map change or wakeUp, navigation is handled — stop here
      // unless there's also a `next` dialogue to chain to
      if ((dialogue.effects.changeMap || dialogue.effects.wakeUp) && !dialogue.next) {
        dispatch({ type: 'ADVANCE_TIME', payload: 5 });
        return;
      }
    }

    // Battle trigger (on the dialogue node itself, not a choice)
    if (dialogue.triggerBattle) {
      dispatchBattle(dialogue.triggerBattle, dialogue.next);
      return;
    }

    dispatch({ type: 'ADVANCE_TIME', payload: 5 });

    // Navigate to next dialogue or back to map
    if (dialogue.randomNext) {
      const pick = dialogue.randomNext[Math.floor(Math.random() * dialogue.randomNext.length)];
      dispatch({ type: 'SET_DIALOGUE', payload: pick });
    } else if (dialogue.next) {
      dispatch({ type: 'SET_DIALOGUE', payload: dialogue.next });
    } else {
      // changeMap on dialogue node (not in effects) — switch map and enter map mode
      if (dialogue.changeMap) {
        dispatch({ type: 'APPLY_EFFECTS', payload: { changeMap: dialogue.changeMap } });
      } else {
        dispatch({ type: 'SET_GAME_MODE', payload: 'map' });
      }
    }
  }, [dialogue, textComplete, showChoices, state.gold, state.quests, dispatch, dispatchBattle]);

  const advanceDialogueRef = useRef(advanceDialogue);
  advanceDialogueRef.current = advanceDialogue;

  // ---------- typewriter ----------

  useEffect(() => {
    if (!dialogue) return;

    setDisplayedText('');
    setTextComplete(false);
    setShowChoices(false);
    if (typewriterIntervalRef.current) {
      clearInterval(typewriterIntervalRef.current);
      typewriterIntervalRef.current = null;
    }

    const fullText = dialogue.text;
    let index = 0;
    const interval = setInterval(() => {
      if (index < fullText.length) {
        setDisplayedText(fullText.substring(0, index + 1));
        index++;
      } else {
        setTextComplete(true);
        clearInterval(interval);
        typewriterIntervalRef.current = null;
        if (dialogue.choices?.length) {
          setTimeout(() => setShowChoices(true), 200);
        }
      }
    }, typewriterSpeed);
    typewriterIntervalRef.current = interval;

    return () => {
      clearInterval(interval);
      typewriterIntervalRef.current = null;
    };
  }, [state.currentDialogue, dialogue?.id]);

  // ---------- CG trigger ----------

  useEffect(() => {
    if (dialogue?.triggerCG && CGS[dialogue.triggerCG]) {
      const cgData = CGS[dialogue.triggerCG];
      setCgActive(true);
      dispatch({ type: 'SET_CG', payload: cgData });

      if (cgTimeoutRef.current) clearTimeout(cgTimeoutRef.current);

      cgTimeoutRef.current = setTimeout(() => {
        dispatch({ type: 'SET_CG', payload: null });
        setCgActive(false);
        advanceDialogueRef.current();
        cgTimeoutRef.current = null;
      }, cgData.duration);
    }

    return () => {
      if (cgTimeoutRef.current) {
        clearTimeout(cgTimeoutRef.current);
        cgTimeoutRef.current = null;
      }
    };
  }, [dialogue?.triggerCG, dispatch]);

  // Allow early CG dismiss via CGView click
  useEffect(() => {
    if (!state.activeCG && cgActive) {
      if (cgTimeoutRef.current) {
        clearTimeout(cgTimeoutRef.current);
        cgTimeoutRef.current = null;
      }
      setCgActive(false);
      advanceDialogueRef.current();
    }
  }, [state.activeCG, cgActive]);

  // ---------- quest completion notifications ----------

  useEffect(() => {
    const prevQuests = prevQuestsRef.current;
    Object.keys(state.quests).forEach(qId => {
      if (state.quests[qId].status === 'completed' && prevQuests[qId]?.status !== 'completed') {
        dispatch({
          type: 'SHOW_NOTIFICATION',
          payload: { message: `🎉 Quest completed: ${state.quests[qId].name}`, duration: 5000 },
        });
      }
    });
    prevQuestsRef.current = state.quests;
  }, [state.quests, dispatch]);

  // ---------- choice handler ----------

  const handleChoice = (choice) => {
    // Special actions (no effects/next needed)
    if (choice.action === 'gift') {
      dispatch({ type: 'START_GIFT', payload: choice.girlId });
      return;
    }
    if (choice.action === 'play') {
      dispatch({ type: 'START_MINIGAME', payload: { girlId: choice.girlId } });
      return;
    }
    if (choice.action === 'start_endless') {
      dispatch({ type: 'START_ENDLESS' });
      return;
    }

    // Validate & apply choice effects
    if (choice.effects) {
      if (choice.effects.requireItem && !(state.inventory[choice.effects.requireItem] > 0)) {
        alert(`You need a ${ITEMS[choice.effects.requireItem]?.name || 'required item'} for this option!`);
        return;
      }
      if (choice.effects.gold && state.gold + choice.effects.gold < 0) {
        alert('Not enough gold!');
        return;
      }
      if (choice.effects.requireAffection) {
        const [charId, min] = Object.entries(choice.effects.requireAffection)[0];
        if ((state.affection[charId] || 0) < min) {
          alert(`You need at least ${min} affection with ${CHARACTERS[charId]?.name || charId}.`);
          return;
        }
      }
      if (choice.effects.consumeItem) {
        dispatch({ type: 'REMOVE_ITEM', payload: choice.effects.consumeItem });
      }
      // Notify newly accepted quests
      if (choice.effects.quests) {
        Object.entries(choice.effects.quests).forEach(([questId, status]) => {
          if (status === 'active' && state.quests[questId]?.status !== 'active') {
            const quest = QUESTS[questId];
            if (quest) {
              dispatch({
                type: 'SHOW_NOTIFICATION',
                payload: { message: `📜 Quest accepted: ${quest.name}` },
              });
            }
          }
        });
      }
      // startMinigame in choice effects
      if (choice.effects.startMinigame) {
        dispatch({ type: 'APPLY_EFFECTS', payload: choice.effects });
        dispatch({ type: 'START_MINIGAME', payload: choice.effects.startMinigame });
        return;
      }
      dispatch({ type: 'APPLY_EFFECTS', payload: choice.effects });
    }

    // Battle trigger from choice
    if (choice.triggerBattle) {
      dispatchBattle(choice.triggerBattle, choice.next);
      return;
    }

    dispatch({ type: 'ADVANCE_TIME', payload: 15 });

    if (choice.next) {
      dispatch({ type: 'SET_DIALOGUE', payload: choice.next });
    } else {
      dispatch({ type: 'SET_GAME_MODE', payload: 'map' });
    }
  };

  // ---------- render ----------

  if (!dialogue) return <div style={{ color: '#fff', padding: 20 }}>Dialogue not found: {state.currentDialogue}</div>;
  const speakerChar = dialogue.speaker ? CHARACTERS[dialogue.speaker] : null;
  const bgStyle = dialogue.background || 'linear-gradient(180deg, #1a1a2e 0%, #2a2a3e 50%, #1a1a2e 100%)';

  return (
    <div
      className="dialogue-view"
      style={{ background: bgStyle }}
      onClick={() => {
        if (cgActive) return;
        if (dialogue.unskippable && !textComplete) return;
        // Only advance on click if choices are not shown (or there are none)
        if (!showChoices || !dialogue.choices?.length) advanceDialogue();
      }}
    >
      {speakerChar && (
        <div className="speaker-portrait">
          {speakerChar.fullPortrait || speakerChar.portrait}
        </div>
      )}
      <div className="dialogue-box" onClick={e => e.stopPropagation()}>
        {speakerChar && <div className="speaker-name">{speakerChar.name}</div>}
        <div className="dialogue-text">
          {displayedText}
          {!textComplete && '▌'}
        </div>
        {showChoices && dialogue.choices?.length > 0 && (
          <div className="choices">
            {dialogue.choices.map((choice, i) => (
              <button key={i} onClick={() => handleChoice(choice)}>
                {choice.text}
              </button>
            ))}
          </div>
        )}
        {textComplete && (!dialogue.choices?.length || !showChoices) && (
          <div className="continue-hint">Click or press to continue... ▼</div>
        )}
      </div>
      {!textComplete && !cgActive && <div className="skip-hint">Click to skip</div>}
    </div>
  );
}