import { useState, useEffect, useRef, useCallback } from 'react';
import { useGame } from './context/GameContext';
import MapView from './components/MapView';
import DialogueView from './components/DialogueView';
import BattleView from './components/BattleView';
import CGView from './components/CGView';
import MenuOverlay from './components/MenuOverlay';
import TitleScreen from './components/TitleScreen';
import MinigameView from './components/MinigameView';
import GiftView from './components/GiftView';
import GachaView from './components/GachaView';

const BASE_WIDTH = 900;
const BASE_HEIGHT = 600;

function Toast({ notification, dispatch }) {
  useEffect(() => {
    const timer = setTimeout(() => dispatch({ type: 'HIDE_NOTIFICATION' }), notification.duration || 3000);
    return () => clearTimeout(timer);
  }, [notification, dispatch]);

  return (
    <div style={{
      position: 'absolute', top: 10, right: 10, zIndex: 300,
      background: 'rgba(0,0,0,0.9)', color: '#ffd700', padding: '10px 20px',
      borderRadius: 8, border: '1px solid #ffd700', fontSize: 14, fontWeight: 'bold',
      boxShadow: '0 0 15px rgba(255,215,0,0.5)'
    }}>
      {notification.message}
    </div>
  );
}

export default function App() {
  const { state, dispatch } = useGame();
  const [showTitle, setShowTitle] = useState(true);
  const rootRef = useRef(null);
  const [scale, setScale] = useState(1);

  useEffect(() => {
    if (!showTitle) {
      const saved = localStorage.getItem('isekai_save');
      if (saved) {
        if (window.confirm('Saved game found. Load it?')) {
          dispatch({ type: 'LOAD_GAME', payload: JSON.parse(saved) });
        } else {
          dispatch({ type: 'INIT_CHARACTER_STATUS', payload: state.party });
        }
      } else {
        dispatch({ type: 'INIT_CHARACTER_STATUS', payload: state.party });
      }
    }
  }, [showTitle]);

  useEffect(() => {
    const handleKey = (e) => {
      if (e.ctrlKey && e.altKey && e.key.toLowerCase() === 'd') {
        const passcode = window.prompt('Enter dev passcode:');
        if (passcode === 'isekaidev') {
          if (!state.showDevInfo) {
            dispatch({ type: 'DEV_MAX_OUT' });
          } else {
            // Already in dev mode – toggle off (optional)
            dispatch({ type: 'TOGGLE_DEV_INFO' });
          }
        }
      }
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [dispatch, state.showDevInfo]);

  const updateScale = useCallback(() => {
    if (!rootRef.current) return;
    const { clientWidth, clientHeight } = rootRef.current;
    setScale(Math.min(clientWidth / BASE_WIDTH, clientHeight / BASE_HEIGHT));
  }, []);

  useEffect(() => {
    updateScale();
    window.addEventListener('resize', updateScale);
    return () => window.removeEventListener('resize', updateScale);
  }, [updateScale]);

  if (showTitle) {
    return <TitleScreen onStart={() => { setShowTitle(false); dispatch({ type: 'SET_GAME_MODE', payload: 'dialogue' }); dispatch({ type: 'SET_DIALOGUE', payload: 'game_start' }); }} />;
  }

  return (
    <div ref={rootRef} style={{ width: '100%', height: '100%', position: 'relative', overflow: 'hidden' }}>
      <div style={{ width: BASE_WIDTH, height: BASE_HEIGHT, position: 'absolute', top: '50%', left: '50%', transform: `translate(-50%, -50%) scale(${scale})`, transformOrigin: 'center center' }}>
        {state.gameMode === 'map' && <MapView scale={scale} />}
        {state.gameMode === 'dialogue' && <DialogueView />}
        {(state.gameMode === 'battle' || state.gameMode === 'endless') && <BattleView />}
        {state.gameMode === 'minigame' && <MinigameView />}
        {state.gameMode === 'gifting' && <GiftView />}
        {state.gameMode === 'recruitment' && <GachaView />}
        {state.menuOpen && <MenuOverlay />}
        {state.activeCG && <CGView />}
        {state.notification && <Toast notification={state.notification} dispatch={dispatch} />}
      </div>
    </div>
  );
}