import React, { useState } from 'react';
import { useGame } from '../context/GameContext';
import { CHARACTERS, ITEMS, SKILLS } from '../data';
import { ASCENSION_DATA, EXP_PER_LEVEL } from '../data/ascensionData';
import { ADVANTAGE_MAP } from '../data/raceAdvantages';

export default function MenuOverlay() {
  const { state, dispatch } = useGame();
  const [activeTab, setActiveTab] = useState('quests');
  const [selectedChar, setSelectedChar] = useState(null);
  const [useItemId, setUseItemId] = useState(null);
  const [showUseModal, setShowUseModal] = useState(false);
  const [ascendPreview, setAscendPreview] = useState(null);

  const tabs = [
    { id: 'quests', label: '📜 Quests' },
    { id: 'inventory', label: '🎒 Inventory' },
    { id: 'characters', label: '👥 Characters' },
    { id: 'lineup', label: '⚔️ Lineup' },
    { id: 'affection', label: '💕 Affection' },
    { id: 'save', label: '💾 Save/Load' },
  ];

  const closeMenu = () => dispatch({ type: 'CLOSE_MENU' });
  const moveToLineup = (charId) => dispatch({ type: 'MOVE_TO_LINEUP', payload: charId });
  const moveToReserve = (charId) => dispatch({ type: 'MOVE_TO_RESERVE', payload: charId });

  const handleUseItem = (charId) => {
    dispatch({ type: 'USE_ITEM_ON_CHARACTER', payload: { itemId: useItemId, charId } });
    setShowUseModal(false);
    setUseItemId(null);
  };

  const canAscend = (charId) => {
    const asc = state.characterAscension[charId] || 0;
    if (asc >= 4) return false;
    const phase = ASCENSION_DATA[charId]?.phases[asc];
    if (!phase) return false;
    if (state.characterLevels[charId] < phase.level) return false;
    if (state.gold < phase.gold) return false;
    for (const [mat, qty] of Object.entries(phase.materials || {})) {
      if ((state.inventory[mat] || 0) < qty) return false;
    }
    return true;
  };

  const tabStyle = (tabId) => ({
    padding: '10px 16px',
    background: activeTab === tabId ? 'rgba(200,150,80,0.3)' : 'transparent',
    color: activeTab === tabId ? '#ffd700' : '#ccc',
    border: 'none',
    borderBottom: activeTab === tabId ? '2px solid #ffd700' : '2px solid transparent',
    cursor: 'pointer',
    fontSize: '14px',
    fontWeight: activeTab === tabId ? 'bold' : 'normal',
    transition: 'all 0.2s',
  });

  return (
    <div
      className="menu-overlay"
      style={{
        position: 'absolute',
        inset: 0,
        zIndex: 100,
        background: 'rgba(10,10,20,0.95)',
        display: 'flex',
        flexDirection: 'column',
        backdropFilter: 'blur(5px)',
      }}
    >
      <div
        style={{
          padding: '12px 20px',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          borderBottom: '1px solid rgba(255,255,255,0.2)',
        }}
      >
        <span style={{ color: '#ffd700', fontSize: 20, fontWeight: 'bold' }}>📋 Menu</span>
        <span style={{ color: '#ccc' }}>💰 {state.gold}g</span>
        <button
          onClick={closeMenu}
          style={{
            background: 'rgba(255,255,255,0.1)',
            color: '#fff',
            border: '1px solid rgba(255,255,255,0.3)',
            padding: '8px 16px',
            borderRadius: 6,
            cursor: 'pointer',
            fontSize: 14,
          }}
        >
          ✕ Close [M]
        </button>
      </div>

      <div style={{ display: 'flex', borderBottom: '1px solid rgba(255,255,255,0.1)', padding: '0 10px' }}>
        {tabs.map((tab) => (
          <button
            key={tab.id}
            onClick={() => {
              setActiveTab(tab.id);
              setSelectedChar(null);
            }}
            style={tabStyle(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </div>

      <div style={{ flex: 1, overflowY: 'auto', padding: 20, color: '#e0d8c8' }}>
        {activeTab === 'quests' && <QuestsTab state={state} dispatch={dispatch} />}
        {activeTab === 'inventory' && (
          <InventoryTab
            state={state}
            dispatch={dispatch}
            onUseItem={(itemId) => {
              setUseItemId(itemId);
              setShowUseModal(true);
            }}
          />
        )}
        {activeTab === 'characters' && (
          <div>
            <h3>👥 Characters</h3>
            {state.party
              .filter((id) => id !== 'protagonist')
              .map((charId) => {
                const char = CHARACTERS[charId];
                if (!char) return null;
                return (
                  <button
                    key={charId}
                    onClick={() => setSelectedChar(charId)}
                    style={{
                      display: 'block',
                      width: '100%',
                      margin: '5px 0',
                      padding: 8,
                      background: '#333',
                      color: '#ffd700',
                      border: '1px solid #555',
                      borderRadius: 4,
                      cursor: 'pointer',
                      textAlign: 'left',
                    }}
                  >
                    {char.portrait} {char.name} Lv.{state.characterLevels[charId] || 1}
                  </button>
                );
              })}
            {selectedChar && (
              <CharacterDetail
                charId={selectedChar}
                state={state}
                dispatch={dispatch}
                canAscend={canAscend}
                onBack={() => setSelectedChar(null)}
                onAscendPreview={(id) => setAscendPreview(id)}
              />
            )}
            {state.party.filter((id) => id !== 'protagonist').length === 0 && (
              <div className="empty-message">No companions recruited yet.</div>
            )}
            <RaceAdvantageDisplay />
          </div>
        )}
        {activeTab === 'lineup' && (
          <LineupTab state={state} moveToLineup={moveToLineup} moveToReserve={moveToReserve} />
        )}
        {activeTab === 'affection' && <AffectionTab state={state} />}
        {activeTab === 'save' && <SaveLoadTab state={state} dispatch={dispatch} />}
      </div>

      {showUseModal && (
        <div
          style={{
            position: 'absolute',
            inset: 0,
            background: 'rgba(0,0,0,0.95)',
            zIndex: 200,
            padding: 20,
            color: '#fff',
          }}
        >
          <h3>Use {ITEMS[useItemId]?.name || 'item'} on</h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            {state.activeLineup.map((charId) => {
              const char = CHARACTERS[charId];
              if (!char) return null;
              const status = state.characterStatus[charId] || {};
              const curHp = status.currentHp ?? char.stats.hp;
              const maxHp = status.baseHp || char.stats.hp;
              const curMp = status.currentMp ?? char.stats.mp;
              const maxMp = status.baseMp || char.stats.mp;
              return (
                <div
                  key={charId}
                  onClick={() => handleUseItem(charId)}
                  style={{
                    background: '#333',
                    padding: 10,
                    borderRadius: 6,
                    cursor: 'pointer',
                    border: '1px solid #ffd700',
                  }}
                >
                  <span>
                    {char.portrait} {char.name}
                  </span>
                  <div
                    style={{
                      background: '#555',
                      height: 6,
                      marginTop: 4,
                      borderRadius: 3,
                    }}
                  >
                    <div
                      style={{
                        width: `${Math.max(0, (curHp / maxHp) * 100)}%`,
                        height: '100%',
                        background: '#e74c3c',
                        transition: 'width 0.4s',
                      }}
                    />
                  </div>
                  <div
                    style={{
                      background: '#555',
                      height: 4,
                      marginTop: 2,
                      borderRadius: 2,
                    }}
                  >
                    <div
                      style={{
                        width: `${Math.max(0, (curMp / maxMp) * 100)}%`,
                        height: '100%',
                        background: '#3498db',
                        transition: 'width 0.4s',
                      }}
                    />
                  </div>
                </div>
              );
            })}
          </div>
          <button
            onClick={() => setShowUseModal(false)}
            style={{
              marginTop: 20,
              padding: '8px 14px',
              background: '#555',
              color: '#fff',
              border: 'none',
              borderRadius: 4,
              cursor: 'pointer',
            }}
          >
            Cancel
          </button>
        </div>
      )}
      {ascendPreview && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.95)',
          zIndex: 200, padding: 20, color: '#fff', overflowY: 'auto'
        }}>
          <h3 style={{ color: '#ffd700' }}>Ascension Preview – {CHARACTERS[ascendPreview]?.name}</h3>
          {(() => {
            const charId = ascendPreview;
            const asc = state.characterAscension[charId] || 0;
            const phase = ASCENSION_DATA[charId]?.phases[asc];
            if (!phase) return <p>Max ascension reached.</p>;

            const char = CHARACTERS[charId];
            const oldStatus = state.characterStatus[charId] || {};
            const boost = phase.statsBoost || {};

            // Current vs new stats
            const oldAtk = oldStatus.atk || char.stats.atk;
            const newAtk = oldAtk + (boost.atk || 0);
            const oldDef = oldStatus.def || char.stats.def;
            const newDef = oldDef + (boost.def || 0);
            const oldSpd = oldStatus.spd || char.stats.spd;
            const newSpd = oldSpd + (boost.spd || 0);
            const oldMag = oldStatus.mag || char.stats.mag;
            const newMag = oldMag + (boost.mag || 0);

            // Materials needed
            const materials = phase.materials || {};
            const canAfford = Object.entries(materials).every(([matId, qty]) => (state.inventory[matId] || 0) >= qty)
                              && state.gold >= phase.gold
                              && (state.characterLevels[charId] || 1) >= phase.level;

            return (
              <>
                <div style={{ margin: '10px 0' }}>
                  <strong>Stats change:</strong>
                  <ul>
                    {Object.keys(boost).length === 0 ? <li>No stat change</li> : (
                      <>
                        {boost.atk ? <li>ATK: {oldAtk} → {newAtk} (+{boost.atk})</li> : null}
                        {boost.def ? <li>DEF: {oldDef} → {newDef} (+{boost.def})</li> : null}
                        {boost.spd ? <li>SPD: {oldSpd} → {newSpd} (+{boost.spd})</li> : null}
                        {boost.mag ? <li>MAG: {oldMag} → {newMag} (+{boost.mag})</li> : null}
                      </>
                    )}
                  </ul>
                </div>
                <div style={{ margin: '10px 0' }}>
                  <strong>Skill change:</strong>
                  {phase.unlocks === 'skill2' ? (
                    <p>Unlocks second skill: {SKILLS[char.skill2]?.name || char.skill2}</p>
                  ) : phase.upgrades ? (
                    <ul>
                      {Object.entries(phase.upgrades).map(([oldSkillId, upgrade]) => (
                        <li key={oldSkillId}>{SKILLS[oldSkillId]?.name || oldSkillId} → {upgrade.name} (Power: {upgrade.power})</li>
                      ))}
                    </ul>
                  ) : <p>No skill changes.</p>}
                </div>
                <div style={{ margin: '10px 0' }}>
                  <strong>Required materials:</strong>
                  <ul>
                    {Object.entries(materials).map(([matId, qty]) => {
                      const owned = state.inventory[matId] || 0;
                      return (
                        <li key={matId} style={{ color: owned >= qty ? '#2ecc71' : '#e74c3c' }}>
                          {ITEMS[matId]?.name || matId} x{qty} (Own: {owned})
                        </li>
                      );
                    })}
                    <li style={{ color: state.gold >= phase.gold ? '#2ecc71' : '#e74c3c' }}>
                      Gold: {phase.gold} (Own: {state.gold})
                    </li>
                  </ul>
                </div>
                <div style={{ display: 'flex', gap: 10, marginTop: 20 }}>
                  <button onClick={() => {
                    dispatch({ type: 'ASCEND_CHARACTER', payload: { charId } });
                    setAscendPreview(null);
                  }} disabled={!canAfford}
                    style={{
                      padding: '10px 20px', background: canAfford ? '#ffd700' : '#555', color: '#000',
                      border: 'none', borderRadius: 6, cursor: canAfford ? 'pointer' : 'not-allowed'
                    }}>
                    Confirm Ascend
                  </button>
                  <button onClick={() => setAscendPreview(null)}
                    style={{ padding: '10px 20px', background: '#555', color: '#fff', border: 'none', borderRadius: 6, cursor: 'pointer' }}>
                    Cancel
                  </button>
                </div>
              </>
            );
          })()}
        </div>
      )}
    </div>
  );
}

// ---------- Sub-components (all inside this file) ----------

function QuestsTab({ state, dispatch }) {
  const mainQuests = Object.values(state.quests).filter((q) => q.type === 'main');
  const sideQuests = Object.values(state.quests).filter((q) => q.type === 'side');

  const renderQuest = (quest) => (
    <div key={quest.id} className="quest-item">
      <div className="quest-header">
        <span className="quest-name">{quest.name}</span>
        <span
          className="quest-status"
          style={{ color: quest.status === 'active' ? '#ffd700' : '#2ecc71' }}
        >
          {quest.status}
        </span>
      </div>
      <div className="quest-description">{quest.description}</div>
      {quest.objectives && (
        <div className="quest-objectives">
          Objectives:
          {quest.objectives.map((obj, i) => (
            <div key={i}>• {obj.description || obj.type}</div>
          ))}
        </div>
      )}
      {quest.rewards && (
        <div className="quest-rewards">
          Rewards: {quest.rewards.gold}g{quest.rewards.items?.length ? ' + Items' : ''}
        </div>
      )}
      {quest.status === 'active' && (
        <button
          onClick={() =>
            dispatch({
              type: 'SET_TRACKED_QUEST',
              payload: state.trackedQuestId === quest.id ? null : quest.id,
            })
          }
          style={{
            marginTop: 6,
            padding: '4px 10px',
            fontSize: 12,
            background: state.trackedQuestId === quest.id ? '#ffd700' : '#333',
            color: state.trackedQuestId === quest.id ? '#000' : '#ccc',
            border: 'none',
            borderRadius: 4,
            cursor: 'pointer',
          }}
        >
          {state.trackedQuestId === quest.id ? '✓ Tracked' : 'Track'}
        </button>
      )}
    </div>
  );

  return (
    <div>
      <h3>🌟 Main Quests</h3>
      {mainQuests.length > 0 ? mainQuests.map(renderQuest) : <div className="empty-message">No main quests.</div>}
      <h3>📋 Side Quests</h3>
      {sideQuests.length > 0 ? sideQuests.map(renderQuest) : <div className="empty-message">No side quests available.</div>}
    </div>
  );
}

function InventoryTab({ state, dispatch, onUseItem }) {
  const inventoryEntries = Object.entries(state.inventory).filter(([_, count]) => count > 0);

  return (
    <div>
      <h3>🎒 Inventory</h3>
      {inventoryEntries.length === 0 ? (
        <div className="empty-message">Your inventory is empty.</div>
      ) : (
        <div className="inventory-list">
          {inventoryEntries.map(([itemId, count]) => {
            const item = ITEMS[itemId];
            if (!item) return null;
            return (
              <div key={itemId} className="inventory-item">
                <div>
                  <div className="item-name">{item.name}</div>
                  <div className="item-desc">{item.description}</div>
                  <div className="item-price">{item.price}g</div>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                  <div className="item-count">x{count}</div>
                  {(item.type === 'consumable' && (item.effect.healHp || item.effect.healMp || item.effect.exp)) && (
                    <button
                      onClick={() => onUseItem(itemId)}
                      style={{
                        padding: '4px 10px',
                        background: '#ffd700',
                        color: '#000',
                        border: 'none',
                        borderRadius: 4,
                        cursor: 'pointer',
                        fontWeight: 'bold',
                      }}
                    >
                      Use
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function RaceAdvantageDisplay() {
  const races = ['Elf', 'Beast', 'Goblin', 'Fey', 'Slime'];
  const icons = {
    Elf: '🧝',
    Beast: '🐺',
    Goblin: '👺',
    Fey: '🐱',
    Slime: '🟢',
  };

  return (
    <div style={{ marginTop: 20, padding: 10, background: '#1a1a2e', borderRadius: 8 }}>
      <div style={{ color: '#ffd700', fontWeight: 'bold', marginBottom: 5 }}>Race Advantages (cycle)</div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, overflowX: 'auto', fontSize: 24 }}>
        {races.map((race, idx) => (
          <span key={race} title={`${race}: strong vs ${ADVANTAGE_MAP[race]?.strongAgainst || 'none'}`}>
            {icons[race]} {idx < races.length - 1 && '⟶'}
          </span>
        ))}
      </div>
    </div>
  );
}

function CharacterDetail({ charId, state, dispatch, canAscend, onBack, onAscendPreview }) {
  const char = CHARACTERS[charId];
  if (!char) return null;

  const level = state.characterLevels[charId] || 1;
  const exp = state.characterExp[charId] || 0;
  const asc = state.characterAscension[charId] || 0;
  const status = state.characterStatus[charId] || {};
  const maxHp = status.baseHp || char.stats.hp;
  const maxMp = status.baseMp || char.stats.mp;
  const atk = status.atk || char.stats.atk;
  const def = status.def || char.stats.def;
  const spd = status.spd || char.stats.spd;
  const mag = status.mag || char.stats.mag;
  const affection = state.affection[charId] || 0;

  const currentMaxLevel = (asc + 1) * 5;
  const expForNext = EXP_PER_LEVEL[level] || 1;

  const ascData = ASCENSION_DATA[charId];
  const nextPhase = ascData?.phases[asc]; // next ascension phase

  const ascendPossible = canAscend(charId);

  return (
    <div style={{ background: '#1a1a2e', padding: 15, borderRadius: 8, marginTop: 10 }}>
      <button
        onClick={onBack}
        style={{ background: 'none', color: '#ffd700', border: 'none', fontSize: 18, cursor: 'pointer' }}
      >
        ← Back
      </button>
      <div style={{ textAlign: 'center', fontSize: 32 }}>{char.portrait}</div>
      <div style={{ textAlign: 'center', fontWeight: 'bold', color: '#ffd700', fontSize: 18 }}>
        {char.name}
      </div>
      <div style={{ color: '#ccc', textAlign: 'center' }}>Race: {char.race}</div>
      <div style={{ marginTop: 10 }}>
        <div>Lv. {level} / {currentMaxLevel}</div>
        <div style={{ background: '#333', borderRadius: 4, height: 8, margin: '4px 0' }}>
          <div
            style={{
              width: `${Math.min(100, (exp / expForNext) * 100)}%`,
              height: '100%',
              background: '#2ecc71',
              transition: 'width 0.4s',
            }}
          />
        </div>
        <div style={{ fontSize: 12 }}>
          {exp} / {expForNext} EXP
        </div>
      </div>
      <div style={{ marginTop: 10 }}>
        <div>HP: {maxHp} | MP: {maxMp}</div>
        <div>ATK: {atk} | DEF: {def} | SPD: {spd} | MAG: {mag}</div>
      </div>
      <div style={{ marginTop: 10 }}>
        <div>
          Affection:{' '}
          {'❤️'.repeat(Math.floor(affection / 20))}
          {state.showDevInfo && <span style={{ marginLeft: 6, fontSize: 12, color: '#aaa' }}>({affection})</span>}
        </div>
      </div>
      {asc < 4 && nextPhase && (
        <div style={{ marginTop: 10 }}>
          <div style={{ color: '#ffd700' }}>Next Ascension (Phase {asc + 1}):</div>
          <div>Requires Lv. {nextPhase.level} | Gold: {nextPhase.gold}</div>
          <div>
            Materials:{' '}
            {Object.entries(nextPhase.materials || {}).map(
              ([mat, qty]) => `${ITEMS[mat]?.name || mat} x${qty}`
            ).join(', ') || 'None'}
          </div>
          <button
            onClick={() => onAscendPreview(charId)}   // open the preview instead
            disabled={!ascendPossible}
            style={{
              marginTop: 8,
              padding: '6px 14px',
              background: ascendPossible ? '#ffd700' : '#555',
              color: '#000',
              border: 'none',
              borderRadius: 4,
              cursor: ascendPossible ? 'pointer' : 'not-allowed',
              fontWeight: 'bold',
            }}
          >
            Ascend
          </button>
        </div>
      )}
    </div>
  );
}

function LineupTab({ state, moveToLineup, moveToReserve }) {
  return (
    <div>
      <h3>⚔️ Battle Lineup (Max 4)</h3>
      <div className="lineup-list">
        {state.activeLineup.map((charId) => {
          const char = CHARACTERS[charId];
          if (!char) return null;
          const status = state.characterStatus[charId] || {};
          const curHp = status.currentHp ?? char.stats.hp;
          const maxHp = status.baseHp || char.stats.hp;
          const curMp = status.currentMp ?? char.stats.mp;
          const maxMp = status.baseMp || char.stats.mp;
          return (
            <div key={charId} className="lineup-card active">
              <div className="lineup-portrait">{char.portrait}</div>
              <div className="lineup-name">{char.name}</div>
              <div className="lineup-stats">HP: {curHp}/{maxHp} MP: {curMp}/{maxMp}</div>
              {state.activeLineup.length > 1 && (
                <button className="move-btn reserve-btn" onClick={() => moveToReserve(charId)}>
                  Move to Reserve
                </button>
              )}
            </div>
          );
        })}
      </div>
      <h3>🛡️ Reserve</h3>
      <div className="lineup-list">
        {state.reserveParty.map((charId) => {
          const char = CHARACTERS[charId];
          if (!char) return null;
          const status = state.characterStatus[charId] || {};
          const curHp = status.currentHp ?? char.stats.hp;
          const maxHp = status.baseHp || char.stats.hp;
          const curMp = status.currentMp ?? char.stats.mp;
          const maxMp = status.baseMp || char.stats.mp;
          return (
            <div key={charId} className="lineup-card reserve">
              <div className="lineup-portrait">{char.portrait}</div>
              <div className="lineup-name">{char.name}</div>
              <div className="lineup-stats">HP: {curHp}/{maxHp} MP: {curMp}/{maxMp}</div>
              <button className="move-btn lineup-btn" onClick={() => moveToLineup(charId)}>
                Add to Lineup
              </button>
            </div>
          );
        })}
        {state.reserveParty.length === 0 && <div className="empty-message">No characters in reserve.</div>}
      </div>
      <div className="lineup-note">💡 Tip: You can rearrange your party at any time from this menu.</div>
    </div>
  );
}

function AffectionTab({ state }) {
  const romanceableChars = Object.values(CHARACTERS).filter((c) => c.isRomanceable);

  return (
    <div>
      <h3>💕 Affection Meter</h3>
      <div className="affection-list">
        {romanceableChars.map((char) => {
          const affection = state.affection[char.id] || 0;
          const maxAffection = 100;
          const percentage = Math.min(100, (affection / maxAffection) * 100);
          const heartColor =
            affection >= 70 ? '#e91e8c' : affection >= 40 ? '#ff6b9d' : affection >= 10 ? '#ffb3c6' : '#666';
          const heartIcon = affection >= 70 ? '❤️' : affection >= 40 ? '💗' : affection >= 10 ? '💛' : '🤍';
          const statusText =
            affection >= 70 ? '💕 Loving' : affection >= 40 ? '😊 Friendly' : affection >= 10 ? '👋 Acquainted' : '😶 Neutral';

          return (
            <div key={char.id} className="affection-card">
              <div className="affection-header">
                <span className="affection-portrait">{char.portrait}</span>
                <span className="affection-name">{char.name}</span>
                <span className="affection-heart" style={{ color: heartColor }}>
                  {heartIcon}
                </span>
              </div>
              <div className="affection-bar-bg">
                <div className="affection-bar-fill" style={{ width: `${percentage}%` }}></div>
              </div>
              <div className="affection-stats">
                <span>
                  {state.showDevInfo ? `${affection} / ${maxAffection}` : ''} {statusText}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function SaveLoadTab({ state, dispatch }) {
  const handleSave = () => {
    const saveData = JSON.stringify(state);
    localStorage.setItem('isekai_save', saveData);
    alert('Progress saved!');
  };
  const handleLoad = () => {
    const saveData = localStorage.getItem('isekai_save');
    if (saveData) {
      try {
        const parsed = JSON.parse(saveData);
        dispatch({ type: 'LOAD_GAME', payload: parsed });
        alert('Game loaded!');
      } catch (e) {
        alert('Corrupted save data.');
      }
    } else {
      alert('No save file found.');
    }
  };
  return (
    <div>
      <button onClick={handleSave} style={{ padding: '10px 20px', marginRight: 10 }}>
        💾 Save Game
      </button>
      <button onClick={handleLoad} style={{ padding: '10px 20px' }}>
        📂 Load Game
      </button>
      <p style={{ color: '#aaa', marginTop: 10 }}>Save your progress locally in this browser.</p>
    </div>
  );
}