import { MAPS, QUESTS, ITEMS, CHARACTERS } from '../data';
import { ASCENSION_DATA, EXP_PER_LEVEL } from '../data/ascensionData';
import { LEVEL_UP_STATS } from '../data/levelUpStats';

export const initialState = {
  gameMode: 'dialogue',
  currentMap: 'home',
  playerPosition: { x: 400, y: 350 },
  party: ['protagonist'],
  activeLineup: ['protagonist'],
  reserveParty: [],
  inventory: {},
  gold: 50,
  quests: {},
  affection: { goddess: 20, elf_archer: 0, cat_girl: 0, wolf_girl: 0, guild_receptionist: 5, lilia: 0, nera: 0, velena: 0 },
  currentDialogue: 'game_start',
  dialogueHistory: [],
  battleState: null,
  activeCG: null,
  menuOpen: false,
  menuActiveTab: null,
  notification: null,
  trackedQuestId: null,
  day: 1, hour: 8, minute: 0,
  characterStatus: {},
  defeatedEnemies: {},
  visitedLocations: [],
  mapQuestPopup: null,
  brothelUnlocked: [],
  minigameData: null,
  giftTarget: null,
  _prevGiftMode: null,
  _prevGiftDialogue: null,
  brothelVisited: false,
  characterLevels: {},
  characterExp: {},
  characterAscension: {},
  showDevInfo: false,
  collectedItems: [],
  goddessDreamPhase: 'none',
  goddessRealmUnlocked: false,
  inDreamVisit: false,
  gachaSparkCount: 0,
  gachaSoftPity: 0,
  firstRecruitBundleUsed: false,
  endlessState: null,
};

/* ========== Helper functions ========== */

function processQuestEvent(state, { type, target, count = 1 }) {
  let newQuests = { ...state.quests };
  let notificationMessage = null;
  let newGold = state.gold;
  let newInv = { ...state.inventory };
  let newAff = { ...state.affection };
  let newVisited = [...(state.visitedLocations || [])];

  if (type === 'visit' && !newVisited.includes(target)) {
    newVisited.push(target);
  }

  for (const qId in newQuests) {
    const q = newQuests[qId];
    if (q.status !== 'active') continue;
    const currentIndex = q.currentObjectiveIndex ?? 0;
    const obj = q.objectives?.[currentIndex];
    if (!obj || obj.type !== type || obj.target !== target) continue;

    const progressKey = obj.id;

    // FIX: 'visit' objectives complete in a single event (count always 1);
    // use max so re-visiting doesn't over-count.
    const currentProg = q.objectiveProgress?.[progressKey]?.currentCount || 0;
    const newCount = type === 'visit' ? obj.count : currentProg + count;
    const completed = newCount >= obj.count;

    newQuests[qId] = {
      ...q,
      objectiveProgress: {
        ...q.objectiveProgress,
        [progressKey]: { currentCount: newCount, completed },
      },
    };

    if (completed) {
      if (currentIndex < q.objectives.length - 1) {
        newQuests[qId].currentObjectiveIndex = currentIndex + 1;
        const nextObj = q.objectives[currentIndex + 1];
        notificationMessage = `📋 Quest objective updated: ${nextObj.description}`;
      } else {
        newQuests[qId].status = 'completed';
        const rewards = q.rewards || {};
        newGold += rewards.gold || 0;
        if (rewards.items)
          rewards.items.forEach(item => (newInv[item] = (newInv[item] || 0) + 1));
        if (rewards.affection)
          Object.entries(rewards.affection).forEach(([cid, v]) => (newAff[cid] = (newAff[cid] || 0) + v));
        notificationMessage = `🎉 Quest completed: ${q.name}!`;
      }
    }
  }

  return {
    ...state,
    quests: newQuests,
    gold: newGold,
    inventory: newInv,
    affection: newAff,
    visitedLocations: newVisited,
    notification: notificationMessage
      ? { message: notificationMessage, duration: 5000 }
      : state.notification,
  };
}

function checkCharQuests(state) {
  const newQuests = { ...state.quests };
  let changed = false;
  const questMap = {
    elf_archer: { part1: 'lyra_quest_part1', part2: 'lyra_quest_part2' },
    cat_girl:   { part1: 'neko_quest_part1',  part2: 'neko_quest_part2'  },
    wolf_girl:  { part1: 'fenra_quest_part1', part2: 'fenra_quest_part2' },
  };

  for (const [charId, quests] of Object.entries(questMap)) {
    const asc = state.characterAscension[charId] || 0;
    const aff = state.affection[charId] || 0;
    const p1 = QUESTS[quests.part1];
    const p2 = QUESTS[quests.part2];

    if (
      p1 &&
      newQuests[quests.part1]?.status === 'available' &&
      asc >= (p1.requiredAscension || 0) &&
      aff >= (p1.requiredAffection || 0)
    ) {
      newQuests[quests.part1] = {
        ...newQuests[quests.part1],
        status: 'active',
        currentObjectiveIndex: 0,
        objectiveProgress: {},
      };
      changed = true;
    }

    if (
      p2 &&
      newQuests[quests.part2]?.status === 'available' &&
      asc >= (p2.requiredAscension || 0) &&
      aff >= (p2.requiredAffection || 0) &&
      newQuests[quests.part1]?.status === 'completed'
    ) {
      newQuests[quests.part2] = {
        ...newQuests[quests.part2],
        status: 'active',
        currentObjectiveIndex: 0,
        objectiveProgress: {},
      };
      changed = true;
    }
  }

  return changed ? { ...state, quests: newQuests } : state;
}

/* ========== Reducer ========== */
export function gameReducer(state, action) {
  switch (action.type) {
    case 'SET_GAME_MODE':
      return { ...state, gameMode: action.payload };

    // FIX: Do not reset inDreamVisit here — it must survive map transitions
    // triggered by dialogue effects (e.g. dream → realm). inDreamVisit is only
    // explicitly cleared via APPLY_EFFECTS { setInDreamVisit: false } or wakeUp.
    case 'SET_MAP':
      return { ...state, currentMap: action.payload, collectedItems: [] };

    case 'SET_POSITION':
      return { ...state, playerPosition: action.payload };

    case 'SET_DIALOGUE':
      return { ...state, currentDialogue: action.payload, gameMode: 'dialogue' };

    case 'ADD_GOLD':
      return { ...state, gold: Math.max(0, state.gold + action.payload) };

    case 'ADD_ITEM': {
      const newInv = { ...state.inventory };
      newInv[action.payload] = (newInv[action.payload] || 0) + 1;
      return { ...state, inventory: newInv };
    }

    case 'REMOVE_ITEM': {
      const newInv = { ...state.inventory };
      if (newInv[action.payload] > 0) {
        newInv[action.payload]--;
        if (newInv[action.payload] === 0) delete newInv[action.payload];
      }
      return { ...state, inventory: newInv };
    }

    case 'SET_AFFECTION': {
      const newAff = { ...state.affection };
      const { charId, amount } = action.payload;
      newAff[charId] = Math.min(100, (newAff[charId] || 0) + amount);
      let newState = { ...state, affection: newAff };
      // Unlock goddess dream once affection reaches 50 (only once)
      if (charId === 'goddess' && newAff[charId] >= 50 && state.goddessDreamPhase === 'none') {
        newState.goddessDreamPhase = 'invited';
      }
      newState = checkCharQuests(newState);
      return newState;
    }

    case 'RECRUIT_CHARACTER': {
      const charId = action.payload;
      if (state.party.includes(charId)) return state;
      const char = CHARACTERS[charId];
      // Also initialise characterStatus so HP/MP bars appear immediately
      const newCharStatus = char
        ? {
            currentHp: char.stats.hp,
            currentMp: char.stats.mp,
            baseHp: char.stats.hp,
            baseMp: char.stats.mp,
            atk: char.stats.atk,
            def: char.stats.def,
            spd: char.stats.spd,
            mag: char.stats.mag,
          }
        : {};
      let newState = {
        ...state,
        party: [...state.party, charId],
        reserveParty: [...state.reserveParty, charId],
        characterLevels: { ...state.characterLevels, [charId]: 1 },
        characterExp: { ...state.characterExp, [charId]: 0 },
        characterAscension: { ...state.characterAscension, [charId]: 0 },
        characterStatus: { ...state.characterStatus, [charId]: newCharStatus },
      };
      newState = checkCharQuests(newState);
      return newState;
    }

    case 'MOVE_TO_LINEUP': {
      const charId = action.payload;
      if (state.activeLineup.length >= 4 || !state.reserveParty.includes(charId)) return state;
      return {
        ...state,
        activeLineup: [...state.activeLineup, charId],
        reserveParty: state.reserveParty.filter(id => id !== charId),
      };
    }

    case 'MOVE_TO_RESERVE': {
      const charId = action.payload;
      if (state.activeLineup.length <= 1 || !state.activeLineup.includes(charId)) return state;
      return {
        ...state,
        activeLineup: state.activeLineup.filter(id => id !== charId),
        reserveParty: [...state.reserveParty, charId],
      };
    }

    case 'SET_BATTLE_STATE': {
      const nextMode = action.payload
        ? (state.gameMode === 'endless' ? 'endless' : 'battle')
        : (state.gameMode === 'endless' ? 'endless' : 'map');
      return { ...state, battleState: action.payload, gameMode: nextMode };
    }

    case 'SET_CG':
      return { ...state, activeCG: action.payload };

    case 'TOGGLE_MENU':
      return { ...state, menuOpen: !state.menuOpen, menuActiveTab: null };

    case 'CLOSE_MENU':
      return { ...state, menuOpen: false, menuActiveTab: null };

    case 'OPEN_MENU_WITH_TAB':
      return { ...state, menuOpen: true, menuActiveTab: action.payload };

    case 'SHOW_NOTIFICATION':
      return { ...state, notification: action.payload };

    case 'HIDE_NOTIFICATION':
      return { ...state, notification: null };

    case 'SET_TRACKED_QUEST':
      return { ...state, trackedQuestId: action.payload };

    case 'QUEST_EVENT':
      return processQuestEvent(state, action.payload);

    case 'ADD_COLLECTED_ITEM':
      if (!state.collectedItems.includes(action.payload))
        return { ...state, collectedItems: [...state.collectedItems, action.payload] };
      return state;

    case 'ADD_DEFEATED_ENEMY': {
      const enemyId = action.payload;
      const newDefeated = { ...state.defeatedEnemies };
      newDefeated[enemyId] = (newDefeated[enemyId] || 0) + 1;
      return { ...state, defeatedEnemies: newDefeated };
    }

    case 'ADD_EXP': {
      const { charId, amount } = action.payload;
      // Skip protagonist and characters not yet recruited
      if (charId === 'protagonist' || !state.characterLevels[charId]) return state;
      const level = state.characterLevels[charId] || 1;
      const asc = state.characterAscension[charId] || 0;
      const maxLevel = (asc + 1) * 5;
      if (level >= maxLevel) return state;

      let exp = (state.characterExp[charId] || 0) + amount;
      let newLevel = level;
      let levelsGained = 0;
      while (exp >= EXP_PER_LEVEL[newLevel] && newLevel < maxLevel) {
        exp -= EXP_PER_LEVEL[newLevel];
        newLevel++;
        levelsGained++;
      }
      if (newLevel >= maxLevel) exp = 0;

      let newState = {
        ...state,
        characterLevels: { ...state.characterLevels, [charId]: newLevel },
        characterExp: { ...state.characterExp, [charId]: exp },
      };

      if (levelsGained > 0) {
        const statGrowth = LEVEL_UP_STATS[charId];
        if (statGrowth) {
          const oldStatus = state.characterStatus[charId] || {};
          const newStatus = { ...oldStatus };
          newStatus.baseHp  = (oldStatus.baseHp  || 0) + statGrowth.hp  * levelsGained;
          newStatus.baseMp  = (oldStatus.baseMp  || 0) + statGrowth.mp  * levelsGained;
          newStatus.atk     = (oldStatus.atk     || 0) + statGrowth.atk * levelsGained;
          newStatus.def     = (oldStatus.def     || 0) + statGrowth.def * levelsGained;
          newStatus.spd     = (oldStatus.spd     || 0) + statGrowth.spd * levelsGained;
          newStatus.mag     = (oldStatus.mag     || 0) + statGrowth.mag * levelsGained;
          // Restore HP/MP by the growth amount (don't exceed new max)
          newStatus.currentHp = Math.min(newStatus.baseHp, (oldStatus.currentHp || 0) + statGrowth.hp * levelsGained);
          newStatus.currentMp = Math.min(newStatus.baseMp, (oldStatus.currentMp || 0) + statGrowth.mp * levelsGained);
          newState = {
            ...newState,
            characterStatus: { ...newState.characterStatus, [charId]: newStatus },
          };
        }
      }
      return checkCharQuests(newState);
    }

    case 'ASCEND_CHARACTER': {
      const { charId } = action.payload;
      const asc = state.characterAscension[charId] || 0;
      if (asc >= 4) return state;
      const phaseData = ASCENSION_DATA[charId]?.phases[asc];
      if (!phaseData) return state;
      if ((state.characterLevels[charId] || 1) < phaseData.level) return state;
      if (state.gold < phaseData.gold) return state;
      for (const [matId, qty] of Object.entries(phaseData.materials || {})) {
        if ((state.inventory[matId] || 0) < qty) return state;
      }

      let newGold = state.gold - phaseData.gold;
      let newInv = { ...state.inventory };
      for (const [matId, qty] of Object.entries(phaseData.materials || {})) {
        newInv[matId] -= qty;
        if (newInv[matId] <= 0) delete newInv[matId];
      }

      let newStatus = { ...state.characterStatus };
      if (phaseData.statsBoost) {
        const boost = phaseData.statsBoost;
        const current = newStatus[charId] || {};
        newStatus[charId] = {
          ...current,
          baseHp: (current.baseHp || 0) + (boost.hp || 0),
          baseMp: (current.baseMp || 0) + (boost.mp || 0),
          atk:    (current.atk    || 0) + (boost.atk || 0),
          def:    (current.def    || 0) + (boost.def || 0),
          spd:    (current.spd    || 0) + (boost.spd || 0),
          mag:    (current.mag    || 0) + (boost.mag || 0),
        };
      }

      let newState = {
        ...state,
        characterAscension: { ...state.characterAscension, [charId]: asc + 1 },
        gold: newGold,
        inventory: newInv,
        characterStatus: newStatus,
      };

      if (phaseData.affectionBoost) {
        const aff = { ...newState.affection };
        aff[charId] = Math.min(100, (aff[charId] || 0) + phaseData.affectionBoost);
        newState = { ...newState, affection: aff };
      }
      return checkCharQuests(newState);
    }

    case 'USE_ITEM_ON_CHARACTER': {
      const { itemId, charId } = action.payload;
      const item = ITEMS[itemId];
      if (!item || !state.inventory[itemId]) return state;

      let newInv = { ...state.inventory };
      newInv[itemId]--;
      if (newInv[itemId] <= 0) delete newInv[itemId];

      const char = CHARACTERS[charId];
      if (!char) return { ...state, inventory: newInv };

      // Handle exp items via ADD_EXP (which also handles level-up side-effects)
      if (item.effect.exp) {
        return gameReducer(
          { ...state, inventory: newInv },
          { type: 'ADD_EXP', payload: { charId, amount: item.effect.exp } }
        );
      }

      let newStatus = { ...state.characterStatus };
      const current = { ...(newStatus[charId] || {}) };
      if (item.effect.healHp) {
        const maxHp = current.baseHp || char.stats.hp;
        current.currentHp = Math.min(maxHp, (current.currentHp || 0) + item.effect.healHp);
      }
      if (item.effect.healMp) {
        const maxMp = current.baseMp || char.stats.mp;
        current.currentMp = Math.min(maxMp, (current.currentMp || 0) + item.effect.healMp);
      }
      newStatus[charId] = current;

      return { ...state, inventory: newInv, characterStatus: newStatus };
    }

    case 'APPLY_EFFECTS': {
      let newState = { ...state };
      const effects = action.payload;
      if (!effects) return newState;

      if (effects.gold !== undefined)
        newState.gold = Math.max(0, newState.gold + effects.gold);

      if (effects.items)
        effects.items.forEach(itemId => {
          newState.inventory = { ...newState.inventory };
          newState.inventory[itemId] = (newState.inventory[itemId] || 0) + 1;
        });

      if (effects.affection) {
        const aff = { ...newState.affection };
        Object.entries(effects.affection).forEach(([cid, amt]) => {
          aff[cid] = Math.min(100, (aff[cid] || 0) + amt);
        });
        newState.affection = aff;
        // Check goddess dream unlock
        if ((aff['goddess'] || 0) >= 50 && newState.goddessDreamPhase === 'none') {
          newState.goddessDreamPhase = 'invited';
        }
      }

      if (effects.recruitCharacter) {
        const charId = effects.recruitCharacter;
        if (!newState.party.includes(charId)) {
          newState = gameReducer(newState, { type: 'RECRUIT_CHARACTER', payload: charId });
        }
      }

      if (effects.fullHeal) {
        const newStatus = { ...newState.characterStatus };
        Object.keys(newStatus).forEach(cid => {
          const char = CHARACTERS[cid];
          if (char)
            newStatus[cid] = {
              ...newStatus[cid],
              currentHp: newStatus[cid]?.baseHp || char.stats.hp,
              currentMp: newStatus[cid]?.baseMp || char.stats.mp,
            };
        });
        newState.characterStatus = newStatus;
      }

      // FIX: Only one of sleep/restHours/wakeUp should advance time.
      // sleep: full night rest → next morning
      if (effects.sleep) {
        newState.day += 1;
        newState.hour = 8;
        newState.minute = 0;
        // Clear dream state on waking from sleep
        newState.inDreamVisit = false;
      }
      // restHours: partial rest, does NOT clear dream state
      if (effects.restHours && !effects.sleep) {
        let totalMin = newState.hour * 60 + newState.minute + effects.restHours * 60;
        while (totalMin >= 1440) {
          totalMin -= 1440;
          newState.day++;
        }
        newState.hour = Math.floor(totalMin / 60);
        newState.minute = totalMin % 60;
      }
      // wakeUp: used when leaving dream realm → next morning, clears dream
      if (effects.wakeUp && !effects.sleep) {
        newState.day += 1;
        newState.hour = 8;
        newState.minute = 0;
        newState.inDreamVisit = false;
      }

      if (effects.changeMap) {
        newState.currentMap = effects.changeMap;
        newState.collectedItems = [];
        const mapData = MAPS[effects.changeMap];
        if (mapData) newState.playerPosition = { ...mapData.playerStart };
        // Always switch to map mode on a terminal map-change effect
        newState.gameMode = 'map';
      }

      if (effects.quests) {
        const q = { ...newState.quests };
        Object.entries(effects.quests).forEach(([qId, status]) => {
          const template = QUESTS[qId];
          if (!template) return;
          if (!q[qId]) {
            q[qId] = { ...template, status, currentObjectiveIndex: 0, objectiveProgress: {} };
          } else {
            q[qId] = { ...q[qId], status };
            // Ensure fresh progress when re-activating
            if (status === 'active' && !q[qId].objectiveProgress) {
              q[qId].currentObjectiveIndex = 0;
              q[qId].objectiveProgress = {};
            }
          }
        });
        newState.quests = q;
        // Show map popup for newly activated quests (only the last one if multiple)
        Object.entries(effects.quests).forEach(([qId, status]) => {
          if (status === 'active') {
            const t = QUESTS[qId];
            if (t)
              newState.mapQuestPopup = {
                questId: qId,
                name: t.name,
                objectiveText: t.objectives?.[0]?.description || '',
              };
          }
        });
      }

      if (effects.questEvent) newState = processQuestEvent(newState, effects.questEvent);

      if (effects.unlockBrothelGirl) {
        if (!newState.brothelUnlocked.includes(effects.unlockBrothelGirl))
          newState.brothelUnlocked = [...newState.brothelUnlocked, effects.unlockBrothelGirl];
      }

      if (effects.brothelVisited) newState.brothelVisited = true;

      if (effects.goddessInviteAccepted) {
        newState.goddessDreamPhase = 'completed';
        newState.goddessRealmUnlocked = true;
      }

      if (effects.setInDreamVisit !== undefined)
        newState.inDreamVisit = effects.setInDreamVisit;

      newState = checkCharQuests(newState);
      return newState;
    }

    case 'ADVANCE_TIME': {
      let totalMin = state.hour * 60 + state.minute + (action.payload || 0);
      let newDay = state.day;
      while (totalMin >= 1440) {
        totalMin -= 1440;
        newDay++;
      }
      return {
        ...state,
        day: newDay,
        hour: Math.floor(totalMin / 60),
        minute: totalMin % 60,
      };
    }

    case 'UPDATE_CHARACTER_STATUS':
      return { ...state, characterStatus: { ...state.characterStatus, ...action.payload } };

    case 'INIT_CHARACTER_STATUS': {
      const status = { ...state.characterStatus };
      (action.payload || []).forEach(cid => {
        const char = CHARACTERS[cid];
        if (char && !status[cid]) {
          // Don't overwrite existing status (loaded save)
          status[cid] = {
            currentHp: char.stats.hp,
            currentMp: char.stats.mp,
            baseHp:    char.stats.hp,
            baseMp:    char.stats.mp,
            atk: char.stats.atk,
            def: char.stats.def,
            spd: char.stats.spd,
            mag: char.stats.mag,
          };
        }
      });
      return { ...state, characterStatus: status };
    }

    case 'LOAD_GAME':
      return { ...initialState, ...action.payload, gameMode: action.payload.gameMode || 'map' };

    case 'SET_MAP_QUEST_POPUP':
      return { ...state, mapQuestPopup: action.payload };

    case 'CLEAR_MAP_QUEST_POPUP':
      return { ...state, mapQuestPopup: null };

    case 'START_MINIGAME':
      // FIX: preserve previous gameMode so END_MINIGAME can return to correct mode
      return {
        ...state,
        gameMode: 'minigame',
        minigameData: { ...action.payload, _prevMode: state.gameMode },
      };

    case 'END_MINIGAME': {
      // FIX: return to whatever mode was active before the minigame started
      const prevMode = state.minigameData?._prevMode || 'map';
      return { ...state, gameMode: prevMode, minigameData: null };
    }

    case 'START_GIFT':
      return { ...state, gameMode: 'gifting', giftTarget: action.payload, _prevGiftMode: state.gameMode, _prevGiftDialogue: state.currentDialogue };

    case 'END_GIFT': {
      const returnMode = state._prevGiftMode || 'map';
      const returnDialogue = state._prevGiftDialogue;
      const base = { ...state, gameMode: returnMode, giftTarget: null, _prevGiftMode: null, _prevGiftDialogue: null };
      // If returning to dialogue, restore the dialogue
      if (returnMode === 'dialogue' && returnDialogue) {
        base.currentDialogue = returnDialogue;
      }
      return base;
    }

    case 'TOGGLE_DEV_INFO':
      return { ...state, showDevInfo: !state.showDevInfo };

    case 'START_RECRUITMENT':
      return { ...state, gameMode: 'recruitment' };

    case 'END_RECRUITMENT':
      return { ...state, gameMode: 'map' };

    case 'PROCESS_GACHA_RESULTS': {
      const { results, cost, newSoftPity, newSpark, isFirstBundle } = action.payload;
      let newState = { ...state };
      newState.gold = Math.max(0, newState.gold - cost);
      if (isFirstBundle) newState.firstRecruitBundleUsed = true;
      newState.gachaSoftPity = newSoftPity;
      newState.gachaSparkCount = newSpark;

      results.forEach(res => {
        if (res.type === 'item') {
          newState = gameReducer(newState, { type: 'ADD_ITEM', payload: res.id });
        } else if (res.type === 'character') {
          if (res.isNew) {
            newState = gameReducer(newState, { type: 'RECRUIT_CHARACTER', payload: res.id });
          } else {
            // Duplicate: bonus affection + materials
            newState = gameReducer(newState, { type: 'SET_AFFECTION', payload: { charId: res.id, amount: 20 } });
            ['windbloom', 'shadow_fur', 'iron_ore'].forEach(mat => {
              newState = gameReducer(newState, { type: 'ADD_ITEM', payload: mat });
            });
          }
        }
      });
      return newState;
    }

    case 'PROCESS_SPARK_CLAIM': {
      const { charId } = action.payload;
      const SPARK_THRESHOLD = 30;
      if (state.gachaSparkCount < SPARK_THRESHOLD) return state;
      let newState = { ...state, gachaSparkCount: 0 };
      if (!newState.party.includes(charId)) {
        newState = gameReducer(newState, { type: 'RECRUIT_CHARACTER', payload: charId });
      } else {
        newState = gameReducer(newState, { type: 'SET_AFFECTION', payload: { charId, amount: 20 } });
        ['windbloom', 'shadow_fur', 'iron_ore'].forEach(mat => {
          newState = gameReducer(newState, { type: 'ADD_ITEM', payload: mat });
        });
      }
      return newState;
    }

    case 'START_ENDLESS': {
      // FIX: guard against empty lineup (protagonist-only party)
      const eligibleIds = state.activeLineup.filter(id => id !== 'protagonist');
      if (eligibleIds.length === 0) return state; // can't start endless with no party
      const party = eligibleIds.map(id => {
        const char = CHARACTERS[id];
        const status = state.characterStatus[id] || {};
        return {
          id,
          name: char.name,
          portrait: char.portrait,
          currentHp: status.currentHp ?? char.stats.hp,
          currentMp: status.currentMp ?? char.stats.mp,
          maxHp: status.baseHp || char.stats.hp,
          maxMp: status.baseMp || char.stats.mp,
          atk: status.atk || char.stats.atk,
          def: status.def || char.stats.def,
          spd: status.spd || char.stats.spd,
          mag: status.mag || char.stats.mag,
          race: char.race,
          skills: [
            ...char.skills,
            ...(state.characterAscension[id] >= 1 && char.skill2 ? [char.skill2] : []),
          ],
        };
      });
      return {
        ...state,
        gameMode: 'endless',
        endlessState: { wave: 1, party, rewards: { gold: 0, exp: 0, items: [] } },
      };
    }

    case 'END_ENDLESS': {
      if (!state.endlessState) return { ...state, gameMode: 'map' };
      const { rewards } = state.endlessState;
      let newState = { ...state, endlessState: null, gameMode: 'map' };
      newState.gold = Math.max(0, newState.gold + rewards.gold);
      const alivePartyIds = state.endlessState.party.map(p => p.id).filter(id => id !== 'protagonist');
      const expPerChar = Math.floor(rewards.exp / Math.max(1, alivePartyIds.length));
      alivePartyIds.forEach(id => {
        newState = gameReducer(newState, { type: 'ADD_EXP', payload: { charId: id, amount: expPerChar } });
      });
      rewards.items.forEach(itemId => {
        newState = gameReducer(newState, { type: 'ADD_ITEM', payload: itemId });
      });
      return newState;
    }

    case 'ADVANCE_ENDLESS_WAVE': {
      if (!state.endlessState) return state;
      const { party, wave, rewards } = state.endlessState;
      // Restore 50% HP/MP between waves
      const newParty = party.map(m => ({
        ...m,
        currentHp: Math.min(m.maxHp, m.currentHp + Math.floor(m.maxHp * 0.5)),
        currentMp: Math.min(m.maxMp, m.currentMp + Math.floor(m.maxMp * 0.5)),
      }));
      const newWave = wave + 1;
      const goldEarned = Math.floor(30 * wave * Math.pow(1.25, wave - 1));
      const expEarned  = Math.floor(20 * wave * Math.pow(1.2,  wave - 1));
      const newItems = [...rewards.items];
      if (wave % 5 === 0) {
        const rareItems = ['lucky_charm', 'silver_ring', 'ruby_earring', 'gold_necklace', 'troll_blood', 'exp_book'];
        newItems.push(rareItems[Math.floor(Math.random() * rareItems.length)]);
      } else if (Math.random() < 0.25) {
        const mats = ['windbloom', 'shadow_fur', 'iron_ore', 'goblin_ear', 'wolf_fang', 'slime_jelly'];
        newItems.push(mats[Math.floor(Math.random() * mats.length)]);
      }
      return {
        ...state,
        endlessState: {
          wave: newWave,
          party: newParty,
          rewards: { gold: rewards.gold + goldEarned, exp: rewards.exp + expEarned, items: newItems },
        },
      };
    }

    case 'UPDATE_ENDLESS_PARTY': {
      if (!state.endlessState) return state;
      return {
        ...state,
        endlessState: { ...state.endlessState, party: action.payload },
      };
    }

    // FIX: DEV_MAX_OUT — removed dead code after return; now correctly uses
    // checkCharQuests to activate all character quests after maxing everything out.
    case 'DEV_MAX_OUT': {
      const maxGold = 999999;
      const maxItems = {};
      Object.keys(ITEMS).forEach(itemId => { maxItems[itemId] = 99; });

      const maxAffection = { ...state.affection };
      Object.values(CHARACTERS).forEach(char => {
        if (char.isRomanceable) maxAffection[char.id] = 100;
      });

      const maxLevels    = { ...state.characterLevels };
      const maxExp       = { ...state.characterExp };
      const maxAscension = { ...state.characterAscension };
      const maxStatus    = { ...state.characterStatus };

      // Recruit all gacha characters if not already in party
      let devParty      = [...state.party];
      let devReserve    = [...state.reserveParty];
      let devCharLevels = { ...maxLevels };
      let devCharExp    = { ...maxExp };
      let devCharAsc    = { ...maxAscension };

      ['elf_archer', 'cat_girl', 'wolf_girl'].forEach(cid => {
        const char = CHARACTERS[cid];
        if (!char) return;

        if (!devParty.includes(cid)) {
          devParty.push(cid);
          devReserve.push(cid);
        }
        devCharLevels[cid] = 20;
        devCharExp[cid]    = 0;
        devCharAsc[cid]    = 4;

        // Compute cumulative stat boosts from all 4 ascension phases
        const phases = ASCENSION_DATA[cid]?.phases || [];
        let totalHp = 0, totalMp = 0, totalAtk = 0, totalDef = 0, totalSpd = 0, totalMag = 0;
        // Level-up stats (levels 1→20)
        const growth = LEVEL_UP_STATS[cid];
        if (growth) {
          totalHp  += growth.hp  * 19;
          totalMp  += growth.mp  * 19;
          totalAtk += growth.atk * 19;
          totalDef += growth.def * 19;
          totalSpd += growth.spd * 19;
          totalMag += growth.mag * 19;
        }
        phases.forEach(phase => {
          const b = phase.statsBoost || {};
          totalHp  += b.hp  || 0;
          totalMp  += b.mp  || 0;
          totalAtk += b.atk || 0;
          totalDef += b.def || 0;
          totalSpd += b.spd || 0;
          totalMag += b.mag || 0;
        });
        const finalHp = char.stats.hp + totalHp;
        const finalMp = char.stats.mp + totalMp;
        maxStatus[cid] = {
          currentHp: finalHp,
          currentMp: finalMp,
          baseHp:    finalHp,
          baseMp:    finalMp,
          atk: char.stats.atk + totalAtk,
          def: char.stats.def + totalDef,
          spd: char.stats.spd + totalSpd,
          mag: char.stats.mag + totalMag,
        };
      });

      let newState = {
        ...state,
        gold:              maxGold,
        inventory:         maxItems,
        affection:         maxAffection,
        characterLevels:   devCharLevels,
        characterExp:      devCharExp,
        characterAscension: devCharAsc,
        characterStatus:   maxStatus,
        party:             devParty,
        reserveParty:      devReserve,
        showDevInfo:       true,
        brothelVisited:    true,
        brothelUnlocked:   ['lilia', 'nera', 'velena'],
        goddessRealmUnlocked: true,
        goddessDreamPhase: 'completed',
      };

      // Activate all available quests whose requirements are now met
      newState = checkCharQuests(newState);
      return newState;
    }

    default:
      return state;
  }
}