import React from 'react';
import { useGame } from '../context/GameContext';

export default function CGView() {
  const { state, dispatch } = useGame();
  const cg = state.activeCG;
  if (!cg) return null;
  return (
    <div
      className="cg-view"
      style={{ background: cg.background }}
      onClick={(e) => {
        e.stopPropagation();               // prevent click from reaching DialogueView
        dispatch({ type: 'SET_CG', payload: null });
      }}
    >
      <div className="cg-overlay">{cg.overlay}</div>
    </div>
  );
}