import React, { useState, useEffect, useRef } from 'react';
import { useGame } from '../context/GameContext';
import { ITEMS, CHARACTERS, CGS } from '../data';

const SINGLE_COST = 150;
const MULTI_COST = 1400;
const FIRST_10_COST = 300;
const SPARK_THRESHOLD = 30;

const FOUR_STAR_ITEMS = [
  'potion', 'mana_potion', 'exp_book',
  'windbloom', 'shadow_fur', 'iron_ore',
  'goblin_ear', 'wolf_fang', 'slime_jelly',
  'lucky_charm', 'silver_ring', 'ruby_earring', 'gold_necklace', 'troll_blood',
];

const FIVE_STAR_CHARS = ['elf_archer', 'cat_girl', 'wolf_girl'];

export default function GachaView() {
  const { state, dispatch } = useGame();
  const [pulling, setPulling] = useState(false);
  const [results, setResults] = useState([]);
  const [showResults, setShowResults] = useState(false);
  const [cgSequence, setCgSequence] = useState([]);
  const [cgIndex, setCgIndex] = useState(-1);
  const [postPullDialogueQueue, setPostPullDialogueQueue] = useState([]);
  const cgTimerRef = useRef(null);

  const spark = state.gachaSparkCount || 0;
  const softPity = state.gachaSoftPity || 0;
  const firstBundleUsed = state.firstRecruitBundleUsed;

  // ---------- CG sequence player ----------
  useEffect(() => {
    if (cgIndex >= 0 && cgIndex < cgSequence.length) {
      const cgData = cgSequence[cgIndex];
      dispatch({ type: 'SET_CG', payload: cgData });
      cgTimerRef.current = setTimeout(() => {
        dispatch({ type: 'SET_CG', payload: null });
        setCgIndex(prev => prev + 1);
      }, cgData.duration);
    } else if (cgIndex >= cgSequence.length && cgSequence.length > 0) {
      setShowResults(true);
      setCgIndex(-1);
    }
    return () => clearTimeout(cgTimerRef.current);
  }, [cgIndex, cgSequence, dispatch]);

  // ---------- pull logic ----------
  const doPull = (count, cost, isFirstBundle = false) => {
    if (pulling || state.gold < cost) return;
    setPulling(true);

    let localSoftPity = softPity;
    let localSpark = spark;
    const pullResults = [];

    // FIX: track characters recruited within this pull so duplicate detection
    // works across the whole multi-pull, not just against the pre-pull party.
    const recruitedThisPull = new Set();

    for (let i = 0; i < count; i++) {
      let result;
      if (localSoftPity >= 9) {
        // Guaranteed 5-star at 10th pull
        result = { type: 'character', id: FIVE_STAR_CHARS[Math.floor(Math.random() * FIVE_STAR_CHARS.length)] };
        localSoftPity = 0;
      } else {
        const roll = Math.random();
        if (roll < 0.05) {
          result = { type: 'character', id: FIVE_STAR_CHARS[Math.floor(Math.random() * FIVE_STAR_CHARS.length)] };
          localSoftPity = 0;
        } else {
          result = { type: 'item', id: FOUR_STAR_ITEMS[Math.floor(Math.random() * FOUR_STAR_ITEMS.length)] };
          localSoftPity++;
        }
      }
      pullResults.push(result);
      localSpark++;
    }

    const newCharacters = [];
    const enrichedResults = pullResults.map(res => {
      if (res.type === 'character') {
        // FIX: check both the existing party AND characters pulled earlier in this batch
        const alreadyOwned = state.party.includes(res.id) || recruitedThisPull.has(res.id);
        res.isNew = !alreadyOwned;
        res.isDuplicate = alreadyOwned;
        if (res.isNew) {
          newCharacters.push(res.id);
          recruitedThisPull.add(res.id);
        }
      }
      return res;
    });

    dispatch({
      type: 'PROCESS_GACHA_RESULTS',
      payload: {
        results: enrichedResults,
        cost,
        newSoftPity: localSoftPity,
        newSpark: localSpark,
        isFirstBundle,
      },
    });

    // Queue CGs for newly recruited characters
    const cgList = enrichedResults
      .filter(r => r.type === 'character' && r.isNew)
      .map(r => CGS[`gacha_${r.id}`])
      .filter(Boolean);

    setResults(enrichedResults);
    setPostPullDialogueQueue(newCharacters.map(cid => `gacha_recruit_${cid}`));

    if (cgList.length > 0) {
      setCgSequence(cgList);
      setCgIndex(0);
    } else {
      setShowResults(true);
    }

    setPulling(false);
  };

  // ---------- spark claim ----------
  const handleSparkClaim = (charId) => {
    if (spark < SPARK_THRESHOLD || pulling) return;
    dispatch({ type: 'PROCESS_SPARK_CLAIM', payload: { charId } });
    const cgId = `gacha_${charId}`;
    const cg = CGS[cgId];
    if (cg) {
      dispatch({ type: 'SET_CG', payload: cg });
      setTimeout(() => {
        dispatch({ type: 'SET_CG', payload: null });
        dispatch({ type: 'END_RECRUITMENT' });
        dispatch({ type: 'SET_DIALOGUE', payload: `gacha_recruit_${charId}` });
      }, cg.duration);
    } else {
      dispatch({ type: 'END_RECRUITMENT' });
      dispatch({ type: 'SET_DIALOGUE', payload: `gacha_recruit_${charId}` });
    }
  };

  // ---------- continue after card reveal ----------
  const handleContinueAfterCards = () => {
    setShowResults(false);
    setResults([]);
    dispatch({ type: 'END_RECRUITMENT' });
    if (postPullDialogueQueue.length > 0) {
      dispatch({ type: 'SET_DIALOGUE', payload: postPullDialogueQueue[0] });
    }
  };

  const closeGacha = () => dispatch({ type: 'END_RECRUITMENT' });

  const canAffordSingle  = state.gold >= SINGLE_COST;
  const canAffordMulti   = state.gold >= MULTI_COST;
  const canAffordFirst10 = !firstBundleUsed && state.gold >= FIRST_10_COST;

  // ---------- render ----------
  return (
    <div style={{
      width: '100%', height: '100%', background: 'rgba(10,10,20,0.97)',
      display: 'flex', flexDirection: 'column', alignItems: 'center',
      justifyContent: 'center', color: '#fff', fontFamily: 'Georgia, serif',
    }}>
      {!showResults && cgIndex < 0 && (
        <>
          <h1 style={{ color: '#ffd700', fontSize: 32, marginBottom: 20 }}>🔮 Recruitment Lounge</h1>
          <p style={{ color: '#ccc', marginBottom: 10 }}>Post a recruitment poster to attract adventurers!</p>

          <div style={{
            background: 'rgba(255,215,0,0.1)', padding: 15, borderRadius: 8,
            marginBottom: 20, border: '1px solid gold',
          }}>
            <p>Spark Points: {spark}/{SPARK_THRESHOLD} &nbsp; Pity: {softPity}/10</p>
            {spark >= SPARK_THRESHOLD && (
              <div style={{ marginTop: 8 }}>
                <button onClick={() => handleSparkClaim('elf_archer')} style={sparkButtonStyle}>🏹 Claim Lyra</button>
                <button onClick={() => handleSparkClaim('cat_girl')}   style={sparkButtonStyle}>🐱 Claim Neko</button>
                <button onClick={() => handleSparkClaim('wolf_girl')}  style={sparkButtonStyle}>🐺 Claim Fenra</button>
              </div>
            )}
          </div>

          <div style={{ display: 'flex', gap: 20 }}>
            <button
              onClick={() => {
                if (canAffordSingle && window.confirm(`Spend ${SINGLE_COST} gold to post a poster?`))
                  doPull(1, SINGLE_COST);
              }}
              disabled={!canAffordSingle || pulling}
              style={pullButtonStyle}
            >
              1× Pull ({SINGLE_COST}g)
            </button>

            {canAffordFirst10 ? (
              <button
                onClick={() => {
                  if (window.confirm(`Use the beginner bundle? 10 pulls for ${FIRST_10_COST} gold!`))
                    doPull(10, FIRST_10_COST, true);
                }}
                disabled={pulling}
                style={{ ...pullButtonStyle, background: '#c84090' }}
              >
                🎁 10× Bundle {FIRST_10_COST}g
              </button>
            ) : (
              <button
                onClick={() => {
                  if (canAffordMulti && window.confirm(`Spend ${MULTI_COST} gold for 10 posters?`))
                    doPull(10, MULTI_COST);
                }}
                disabled={!canAffordMulti || pulling}
                style={pullButtonStyle}
              >
                10× Pull ({MULTI_COST}g)
              </button>
            )}
          </div>

          <button
            onClick={closeGacha}
            style={{
              marginTop: 30, background: '#555', color: '#fff',
              padding: '10px 20px', borderRadius: 6, border: 'none', cursor: 'pointer',
            }}
          >
            Leave Lounge
          </button>
        </>
      )}

      {showResults && (
        <div style={{ width: '80%', maxWidth: 700, overflowY: 'auto', padding: 20 }}>
          <h2 style={{ color: '#ffd700', textAlign: 'center', marginBottom: 10 }}>Recruitment Results</h2>
          <div style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'center', gap: 10 }}>
            {results.map((res, idx) => (
              <div
                key={idx}
                style={{
                  background: res.type === 'character'
                    ? 'linear-gradient(45deg, #5a3a2a, #8a5a3a)'
                    : '#2a2a3a',
                  borderRadius: 10, padding: 12, width: 130, textAlign: 'center',
                  border: res.type === 'character' ? '2px solid gold' : '1px solid #555',
                }}
              >
                {res.type === 'item' ? (
                  <>
                    <div style={{ fontSize: 36 }}>📦</div>
                    <div style={{ fontWeight: 'bold', color: '#ccc' }}>{ITEMS[res.id]?.name || res.id}</div>
                  </>
                ) : (
                  <>
                    <div style={{ fontSize: 36 }}>{CHARACTERS[res.id]?.portrait}</div>
                    <div style={{ fontWeight: 'bold', color: '#ffd700' }}>{CHARACTERS[res.id]?.name}</div>
                    {res.isDuplicate
                      ? <div style={{ color: '#e0a800', fontSize: 12 }}>Duplicate: +20 ❤️ + mats</div>
                      : <div style={{ color: '#5f5', fontSize: 12 }}>NEW ALLY!</div>
                    }
                  </>
                )}
              </div>
            ))}
          </div>
          <button
            onClick={handleContinueAfterCards}
            style={{
              margin: '20px auto', display: 'block', padding: '12px 30px',
              background: '#ffd700', color: '#000', border: 'none', borderRadius: 8,
              cursor: 'pointer', fontWeight: 'bold',
            }}
          >
            Continue
          </button>
        </div>
      )}
    </div>
  );
}

const pullButtonStyle = {
  padding: '15px 30px',
  fontSize: 18,
  background: '#2a2a3a',
  color: '#ffd700',
  border: '2px solid #ffd700',
  borderRadius: 10,
  cursor: 'pointer',
  fontWeight: 'bold',
};

const sparkButtonStyle = {
  padding: '8px 14px',
  margin: '0 5px',
  background: '#ffd700',
  color: '#000',
  border: 'none',
  borderRadius: 6,
  cursor: 'pointer',
};