import React, { useState, useEffect } from 'react';
import { useGame } from '../context/GameContext';

const GAME_MAP = {
  lilia: 'rps',
  nera: 'memory',
  velena: 'dice',
};

export default function MinigameView() {
  const { state, dispatch } = useGame();
  const girlId = state.minigameData?.girlId;
  const gameType = state.minigameData?.gameType || GAME_MAP[girlId] || 'rps';

  const endMinigame = () => {
    const returnDialogue = state.minigameData?.returnDialogue;
    dispatch({ type: 'END_MINIGAME' });
    if (returnDialogue) {
      dispatch({ type: 'SET_DIALOGUE', payload: returnDialogue });
    }
  };

  if (!girlId) return <div>No girl selected.</div>;

  return (
    <div style={{
      width: '100%', height: '100%', background: 'rgba(0,0,0,0.9)',
      display: 'flex', flexDirection: 'column', alignItems: 'center',
      justifyContent: 'center', color: '#ffd700', fontSize: 24
    }}>
      {gameType === 'rps' && <RPSGame girlId={girlId} dispatch={dispatch} onEnd={endMinigame} />}
      {gameType === 'memory' && <MemoryGame girlId={girlId} dispatch={dispatch} onEnd={endMinigame} />}
      {gameType === 'dice' && <DiceGame girlId={girlId} dispatch={dispatch} onEnd={endMinigame} />}
      {gameType === 'quiz' && <QuizGame girlId={girlId} dispatch={dispatch} onEnd={endMinigame} />}
    </div>
  );
}

// ---------- RPS (best‑of‑3) ----------
const CHOICES = ['🪨 Rock', '📄 Paper', '✂️ Scissors'];

function RPSGame({ girlId, dispatch, onEnd }) {
  const [round, setRound] = useState(1);
  const [playerWins, setPlayerWins] = useState(0);
  const [npcWins, setNpcWins] = useState(0);
  const [playerChoice, setPlayerChoice] = useState(null);
  const [npcChoice, setNpcChoice] = useState(null);
  const [result, setResult] = useState(null);
  const [finished, setFinished] = useState(false);

  const play = (pChoice) => {
    const npcIdx = Math.floor(Math.random() * 3);
    const npc = CHOICES[npcIdx];
    setPlayerChoice(pChoice);
    setNpcChoice(npc);

    let res = 'draw';
    if (pChoice !== npc) {
      if ((pChoice === CHOICES[0] && npc === CHOICES[2]) ||
          (pChoice === CHOICES[1] && npc === CHOICES[0]) ||
          (pChoice === CHOICES[2] && npc === CHOICES[1]))
        res = 'win';
      else res = 'lose';
    }
    setResult(res);
    if (res === 'win') setPlayerWins(w => w + 1);
    else if (res === 'lose') setNpcWins(w => w + 1);

    setTimeout(() => {
      if (round >= 3 || playerWins + (res === 'win' ? 1 : 0) >= 2 || npcWins + (res === 'lose' ? 1 : 0) >= 2) {
        setFinished(true);
      } else {
        setRound(r => r + 1);
        setPlayerChoice(null);
        setNpcChoice(null);
        setResult(null);
      }
    }, 1500);
  };

  if (finished) {
    const finalWin = playerWins > npcWins;
    // Goddess: only give affection if the player wins
    if (finalWin && girlId !== 'goddess') {
      dispatch({ type: 'SET_AFFECTION', payload: { charId: girlId, amount: 12 } });
    } else if (finalWin && girlId === 'goddess') {
      // For goddess, winning gives affection (adjust amount if needed)
      dispatch({ type: 'SET_AFFECTION', payload: { charId: girlId, amount: 12 } });
    }
    return (
      <div style={{ textAlign: 'center' }}>
        <h2>Game Over</h2>
        <p>You {finalWin ? 'Win! 🎉' : (playerWins === npcWins ? 'Draw 🤝' : 'Lose 😞')}</p>
        <p>Score: {playerWins} - {npcWins}</p>
        <button onClick={onEnd} style={{ padding: '10px 20px', background: '#ffd700', color: '#000', border: 'none', borderRadius: 8, cursor: 'pointer', fontWeight: 'bold' }}>Continue</button>
      </div>
    );
  }

  return (
    <div>
      <h2>🪨📄✂️ Round {round} / 3</h2>
      <div style={{ marginBottom: 10, fontSize: 18 }}>Wins: You {playerWins} - {npcWins} Opponent</div>
      {!playerChoice ? (
        <div>
          <p>Choose your move:</p>
          {CHOICES.map(c => (
            <button key={c} onClick={() => play(c)} style={{ margin: 5, padding: '10px 20px', fontSize: 18, background: '#333', color: '#fff', border: '1px solid #ffd700', borderRadius: 8, cursor: 'pointer' }}>{c}</button>
          ))}
        </div>
      ) : (
        <div style={{ textAlign: 'center' }}>
          <div>You: {playerChoice}</div>
          <div>She: {npcChoice}</div>
          <div style={{ marginTop: 20, fontSize: 32 }}>
            {result === 'win' ? '🎉 You Win!' : result === 'lose' ? '😞 You Lose' : '🤝 Draw'}
          </div>
        </div>
      )}
    </div>
  );
}

// ---------- Memory Game (fixed) ----------
function MemoryGame({ girlId, dispatch, onEnd }) {
  const [sequence, setSequence] = useState([]);
  const [playerInput, setPlayerInput] = useState([]);
  const [phase, setPhase] = useState('show'); // 'show' or 'input'
  const [showIndex, setShowIndex] = useState(-1);
  const [result, setResult] = useState(null);

  useEffect(() => {
    const len = 4 + Math.floor(Math.random() * 3); // 4‑6
    const seq = Array.from({ length: len }, () => Math.floor(Math.random() * 9) + 1);
    setSequence(seq);
  }, []);

  useEffect(() => {
    if (phase === 'show' && sequence.length > 0) {
      let idx = 0;
      const timer = setInterval(() => {
        setShowIndex(idx);
        idx++;
        if (idx >= sequence.length) {
          clearInterval(timer);
          setTimeout(() => {
            setPhase('input');
            setShowIndex(-1);
          }, 500);
        }
      }, 800);
      return () => clearInterval(timer);
    }
  }, [phase, sequence]);

  const handleClick = (num) => {
    if (phase !== 'input') return;
    const newInput = [...playerInput, num];
    setPlayerInput(newInput);
    if (newInput.length === sequence.length) {
      const correct = newInput.every((v, i) => v === sequence[i]);
      setResult(correct ? 'win' : 'lose');
      setPhase('result');
      if (correct && girlId !== 'goddess') {
        dispatch({ type: 'SET_AFFECTION', payload: { charId: girlId, amount: 12 } });
      } else if (correct && girlId === 'goddess') {
        dispatch({ type: 'SET_AFFECTION', payload: { charId: girlId, amount: 12 } });
      }
      setTimeout(() => onEnd(), 2000);
    }
  };

  return (
    <div style={{ textAlign: 'center' }}>
      <h2>🐾 Memory Game</h2>
      {phase === 'show' && (
        <div style={{ fontSize: 40, margin: '20px 0' }}>
          {showIndex >= 0 ? sequence[showIndex] : '?'}
        </div>
      )}
      {phase === 'input' && (
        <>
          <p>Repeat the sequence:</p>
          <div style={{ display: 'flex', justifyContent: 'center', gap: 10, flexWrap: 'wrap' }}>
            {[1,2,3,4,5,6,7,8,9].map(num => (
              <button key={num} onClick={() => handleClick(num)} style={{
                width: 50, height: 50, fontSize: 24,
                background: '#333', color: '#fff',
                border: '1px solid gold', borderRadius: 8, cursor: 'pointer'
              }}>{num}</button>
            ))}
          </div>
          <div style={{ marginTop: 10 }}>Your input: {playerInput.join(' ')}</div>
        </>
      )}
      {phase === 'result' && (
        <div style={{ fontSize: 32, marginTop: 20 }}>
          {result === 'win' ? '🎉 Correct!' : '😿 Wrong...'}
        </div>
      )}
    </div>
  );
}

// ---------- Dice Duel (best‑of‑3) ----------
function DiceGame({ girlId, dispatch, onEnd }) {
  const [round, setRound] = useState(1);
  const [playerWins, setPlayerWins] = useState(0);
  const [npcWins, setNpcWins] = useState(0);
  const [rolling, setRolling] = useState(false);
  const [playerRoll, setPlayerRoll] = useState(null);
  const [npcRoll, setNpcRoll] = useState(null);
  const [roundResult, setRoundResult] = useState(null);

  const roll = () => {
    setRolling(true);
    setTimeout(() => {
      const p = Math.floor(Math.random() * 6) + 1;
      const v = Math.floor(Math.random() * 6) + 1;
      setPlayerRoll(p);
      setNpcRoll(v);
      const res = p > v ? 'win' : p < v ? 'lose' : 'draw';
      setRoundResult(res);
      if (res === 'win') setPlayerWins(w => w + 1);
      else if (res === 'lose') setNpcWins(w => w + 1);
      setRolling(false);

      setTimeout(() => {
        if (playerWins + (res === 'win' ? 1 : 0) >= 2 || npcWins + (res === 'lose' ? 1 : 0) >= 2) {
          const finalWin = playerWins > npcWins || (res === 'win' && playerWins + 1 === 2);
          if (finalWin && girlId !== 'goddess') {
            dispatch({ type: 'SET_AFFECTION', payload: { charId: girlId, amount: 12 } });
          } else if (finalWin && girlId === 'goddess') {
            dispatch({ type: 'SET_AFFECTION', payload: { charId: girlId, amount: 12 } });
          }
          onEnd();
        } else {
          setRound(r => r + 1);
          setPlayerRoll(null);
          setNpcRoll(null);
          setRoundResult(null);
        }
      }, 1500);
    }, 600);
  };

  return (
    <div>
      <h2>🐺 Velena's Dice Duel</h2>
      <p>Round {round} / Best of 3 – You {playerWins} : {npcWins} Velena</p>
      <button onClick={roll} disabled={rolling} style={{ padding: '15px 30px', fontSize: 24, background: rolling ? '#555' : '#4a2a2a', color: '#fff', border: '2px solid gold', borderRadius: 10, cursor: rolling ? 'not-allowed' : 'pointer', marginBottom: 20 }}>🎲 Roll Dice</button>
      {playerRoll !== null && (
        <div style={{ fontSize: 20 }}>
          <div>You rolled: {playerRoll}</div>
          <div>Velena rolled: {npcRoll}</div>
          <div style={{ marginTop: 10 }}>
            {roundResult === 'win' ? '🎉 You win the round!' : roundResult === 'lose' ? '💔 Velena wins the round' : '🤝 Draw'}
          </div>
        </div>
      )}
    </div>
  );
}

// ---------- Goddess Quiz (fixed scoring) ----------
const QUIZ_QUESTIONS = [
  { question: "What is the Goddess' name?", answers: ["Luminara", "Velena", "Lyra", "Nera"], correct: 0 },
  { question: "What is your divine mission?", answers: ["Defeat the demon lord", "Visit every brothel", "Collect all herbs", "Become king"], correct: 1 },
  { question: "What race is Neko?", answers: ["Elf", "Beast", "Fey", "Slime"], correct: 2 },
];

function QuizGame({ girlId, dispatch, onEnd }) {
  const [currentQ, setCurrentQ] = useState(0);
  const [score, setScore] = useState(0);
  const [selected, setSelected] = useState(null);
  const [finished, setFinished] = useState(false);

  const q = QUIZ_QUESTIONS[currentQ];

  const handleAnswer = (idx) => {
    setSelected(idx);
    const isCorrect = (idx === q.correct);
    if (isCorrect) setScore(s => s + 1);
    setTimeout(() => {
      if (currentQ < QUIZ_QUESTIONS.length - 1) {
        setCurrentQ(c => c + 1);
        setSelected(null);
      } else {
        setFinished(true);
        // Only give affection if at least 2 correct (or all 3) – adjust as needed
        const finalScore = score + (isCorrect ? 1 : 0);
        if (finalScore >= 2 && girlId !== 'goddess') {
          dispatch({ type: 'SET_AFFECTION', payload: { charId: girlId, amount: 10 } });
        } else if (finalScore >= 2 && girlId === 'goddess') {
          dispatch({ type: 'SET_AFFECTION', payload: { charId: girlId, amount: 10 } });
        }
      }
    }, 1000);
  };

  if (finished) {
    return (
      <div style={{ textAlign: 'center' }}>
        <h2>Quiz Complete!</h2>
        <p>You got {score + (selected === q.correct ? 1 : 0)} / {QUIZ_QUESTIONS.length} correct.</p>
        <button onClick={onEnd} style={{ padding: '10px 20px', background: '#ffd700', color: '#000', border: 'none', borderRadius: 8, cursor: 'pointer', fontWeight: 'bold' }}>Continue</button>
      </div>
    );
  }

  return (
    <div style={{ textAlign: 'center', padding: 10 }}>
      <h3>Question {currentQ + 1}/{QUIZ_QUESTIONS.length}</h3>
      <p style={{ fontSize: 20 }}>{q.question}</p>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8, alignItems: 'center' }}>
        {q.answers.map((ans, i) => (
          <button key={i} onClick={() => handleAnswer(i)} disabled={selected !== null}
            style={{ padding: '10px 20px', fontSize: 16, background: selected === i ? (i === q.correct ? '#2ecc71' : '#e74c3c') : '#333', color: '#fff', border: '1px solid gold', borderRadius: 8, cursor: 'pointer', width: '80%' }}>
            {ans}
          </button>
        ))}
      </div>
    </div>
  );
}