export default function TitleScreen({ onStart }) {
  return (
    <div style={{
      width: '100%', height: '100%',
      background: 'linear-gradient(135deg, #0a0a14 0%, #1a1a2e 30%, #2a1a3e 60%, #0a0a14 100%)',
      display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
      color: '#fff', fontFamily: "'Georgia', serif"
    }}>
      <div style={{ fontSize: '48px', fontWeight: 'bold', color: '#ffd700', textShadow: '0 0 30px rgba(255,200,100,0.6)' }}>✨ Isekai Brothel Quest ✨</div>
      <div style={{ fontSize: '18px', color: '#e0c8a0', marginBottom: 30 }}>A Visual Novel RPG Adventure</div>
      <button onClick={onStart} style={{
        padding: '16px 40px', fontSize: 20, fontWeight: 'bold',
        background: 'linear-gradient(135deg, #c84090, #e060a0)',
        color: '#fff', border: '2px solid #ffd700', borderRadius: 30, cursor: 'pointer'
      }}>🌟 BEGIN ADVENTURE</button>
    </div>
  );
}