import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useGame } from '../context/GameContext';
import { MAPS, ENEMY_GROUPS, CHARACTERS, QUESTS } from '../data';

export default function MapView({ scale }) {
  const { state, dispatch } = useGame();
  const mapData = MAPS[state.currentMap];

  const [targetPos, setTargetPos] = useState(null);
  const [nearInteractable, setNearInteractable] = useState(null);
  const [encounterFlash, setEncounterFlash] = useState(false);
  const [encounterExclamation, setEncounterExclamation] = useState(false);
  const [ambushBanner, setAmbushBanner] = useState(false);
  const [stepCount, setStepCount] = useState(0);
  const [showBedMenu, setShowBedMenu] = useState(false);

  const moveSpeed = 3;
  const interactRange = 45;
  const encounterStepThreshold = 80;

  const animFrameRef = useRef(null);
  const playerPosRef = useRef(state.playerPosition);
  const mapDataRef = useRef(mapData);

  useEffect(() => { playerPosRef.current = state.playerPosition; }, [state.playerPosition]);
  useEffect(() => { mapDataRef.current = mapData; }, [mapData]);

  useEffect(() => {
    if (state.mapQuestPopup) {
      const timer = setTimeout(() => dispatch({ type: 'CLEAR_MAP_QUEST_POPUP' }), 6000);
      return () => clearTimeout(timer);
    }
  }, [state.mapQuestPopup]);

  const moveTowardsTarget = useCallback(() => {
    const pos = playerPosRef.current;
    const tgt = targetPos;
    if (!pos || !tgt) return;
    const dx = tgt.x - pos.x;
    const dy = tgt.y - pos.y;
    const dist = Math.sqrt(dx * dx + dy * dy);
    if (dist < 2) {
      dispatch({ type: 'SET_POSITION', payload: { ...tgt } });
      setTargetPos(null);
      return;
    }
    const map = mapDataRef.current;
    let newPos = { x: pos.x, y: pos.y };
    if (Math.abs(dx) > 1) {
      newPos.x += Math.sign(dx) * Math.min(moveSpeed, Math.abs(dx));
    } else if (Math.abs(dy) > 1) {
      newPos.y += Math.sign(dy) * Math.min(moveSpeed, Math.abs(dy));
    } else {
      newPos = { x: tgt.x, y: tgt.y };
    }
    newPos.x = Math.max(10, Math.min((map?.width || 800) - 10, newPos.x));
    newPos.y = Math.max(10, Math.min((map?.height || 500) - 10, newPos.y));
    dispatch({ type: 'SET_POSITION', payload: newPos });
    setStepCount(prev => prev + 1);
  }, [targetPos, dispatch]);

  useEffect(() => {
    if (!targetPos) return;
    const loop = () => {
      moveTowardsTarget();
      animFrameRef.current = requestAnimationFrame(loop);
    };
    animFrameRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(animFrameRef.current);
  }, [targetPos, moveTowardsTarget]);

  useEffect(() => {
    if (!mapData?.randomEncounters) return;
    if (stepCount >= encounterStepThreshold && targetPos && !ambushBanner) {
      if (Math.random() < mapData.randomEncounters.chance) {
        const groups = mapData.randomEncounters.groups;
        const randomGroupId = groups[Math.floor(Math.random() * groups.length)];
        setEncounterFlash(true);
        setEncounterExclamation(true);
        setAmbushBanner(true);
        setTimeout(() => {
          setAmbushBanner(false);
          setEncounterFlash(false);
          setEncounterExclamation(false);
          startBattle(randomGroupId);
        }, 2000);
      }
      setStepCount(0);
    }
  }, [stepCount, mapData, targetPos, ambushBanner]);

  useEffect(() => {
    if (state.gameMode !== 'map') return;
    const isNight = state.hour >= 20 || state.hour < 6;
    const isOutdoors = state.currentMap === 'plains' || state.currentMap === 'forest';
    if (isOutdoors && isNight) {
      dispatch({
        type: 'SHOW_NOTIFICATION',
        payload: { message: '🌙 Night falls quickly. You hurry back to town.' },
      });
      dispatch({ type: 'SET_MAP', payload: 'town' });
      const townMap = MAPS['town'];
      dispatch({ type: 'SET_POSITION', payload: { ...townMap.playerStart } });
    }
  }, [state.hour, state.currentMap, state.gameMode, dispatch]);

  useEffect(() => {
    if (state.gameMode !== 'map' || !mapData) return;
    const pos = state.playerPosition;
    const nearby = (mapData.interactables || []).find(obj => {
      if (obj.type === 'item' && state.collectedItems.includes(obj.id)) return false;
      const dx = pos.x - obj.x;
      const dy = pos.y - obj.y;
      return Math.sqrt(dx * dx + dy * dy) < interactRange;
    });
    setNearInteractable(nearby || null);
  }, [state.playerPosition, mapData, state.gameMode, state.collectedItems]);

  const handleMapClick = (e) => {
    if (
      e.target.closest('.interactable') ||
      e.target.closest('.menu-button') ||
      e.target.closest('button') ||
      showBedMenu ||
      ambushBanner
    )
      return;
    const rect = e.currentTarget.getBoundingClientRect();
    const x = (e.clientX - rect.left) / scale;
    const y = (e.clientY - rect.top) / scale;
    setTargetPos({ x, y });
  };

  const startBattle = useCallback((enemyGroupId) => {
    const group = ENEMY_GROUPS[enemyGroupId];
    if (!group) return;
    const enemies = group.enemies.map((eId, i) => ({
      ...CHARACTERS[eId],
      battleId: `${eId}_${i}_${Date.now()}`,
      currentHp: CHARACTERS[eId].stats.hp,
      currentMp: CHARACTERS[eId].stats.mp,
    }));
    const party = state.activeLineup.map(cId => {
      const char = CHARACTERS[cId];
      const status = state.characterStatus[cId] || {};
      const asc = state.characterAscension[cId] || 0;
      const allSkills = [...char.skills];
      if (asc >= 1 && char.skill2) allSkills.push(char.skill2);
      const maxHp = status.baseHp || char.stats.hp;
      const maxMp = status.baseMp || char.stats.mp;
      return {
        ...char,
        skills: allSkills,
        battleId: cId,
        currentHp: status.currentHp ?? maxHp,
        currentMp: status.currentMp ?? maxMp,
        stats: {
          ...char.stats,
          hp: maxHp,
          maxHp,
          mp: maxMp,
          maxMp,
          atk: status.atk || char.stats.atk,
          def: status.def || char.stats.def,
          spd: status.spd || char.stats.spd,
          mag: status.mag || char.stats.mag,
        },
      };
    });
    dispatch({
      type: 'SET_BATTLE_STATE',
      payload: {
        enemyGroupId,
        enemies,
        party,
        turnOrder: [],
        currentTurnIndex: 0,
        phase: 'player_turn',
        selectedAction: null,
        battleLog: ['⚔️ Battle started!'],
        goldReward: group.goldReward,
        itemRewards: group.itemRewards,
        expReward: group.expReward,
        returnDialogue: null,
      },
    });
  }, [dispatch, state.activeLineup, state.characterStatus, state.characterAscension]);

  const handleInteraction = useCallback((obj) => {
    if (!obj || showBedMenu || ambushBanner) return;

    if (obj.id === 'bed') {
      setShowBedMenu(true);
      return;
    }

    if (obj.id === 'realm_exit') {
      dispatch({ type: 'APPLY_EFFECTS', payload: { wakeUp: true, changeMap: 'home', setInDreamVisit: false } });
      return;
    }

    if (obj.id === 'realm_goddess') {
      if (state.inDreamVisit) {
        dispatch({ type: 'SET_DIALOGUE', payload: 'goddess_dream_interact' });
      } else {
        dispatch({ type: 'SET_DIALOGUE', payload: 'goddess_realm_interact' });
      }
      return;
    }

    if (obj.type === 'item') {
      if (state.collectedItems.includes(obj.id)) return;
      dispatch({ type: 'SET_DIALOGUE', payload: obj.dialogueId });
      dispatch({ type: 'ADD_ITEM', payload: obj.itemId });
      dispatch({ type: 'ADD_COLLECTED_ITEM', payload: obj.id });
      dispatch({ type: 'ADVANCE_TIME', payload: 10 });
      if (obj.itemId) {
        dispatch({ type: 'QUEST_EVENT', payload: { type: 'collect', target: obj.itemId, count: 1 } });
      }
      return;
    }

    // Time restrictions
    if (obj.id === 'forest_path' && (state.hour >= 20 || state.hour < 6)) {
      dispatch({ type: 'SET_DIALOGUE', payload: 'forest_night_warning' });
      return;
    }
    if ((obj.id === 'brothel' || obj.id === 'guild_entrance') && (state.hour >= 22 || state.hour < 7)) {
      dispatch({ type: 'SET_DIALOGUE', payload: 'closed_dialogue' });
      return;
    }
    if (obj.requiresLevel) {
      const canEnter = state.activeLineup.some(id => (state.characterLevels[id] || 1) >= obj.requiresLevel);
      if (!canEnter) {
        dispatch({ type: 'SHOW_NOTIFICATION', payload: { message: `You need a character at least level ${obj.requiresLevel} to enter.` } });
        return;
      }
    }

    // Brothel entrance
    if (obj.id === 'brothel') {
      if (state.brothelVisited) {
        dispatch({ type: 'SET_MAP', payload: 'brothel_map' });
        const brothelMap = MAPS['brothel_map'];
        dispatch({ type: 'SET_POSITION', payload: { ...brothelMap.playerStart } });
        dispatch({ type: 'SET_GAME_MODE', payload: 'map' });
      } else {
        dispatch({ type: 'SET_DIALOGUE', payload: 'brothel_entrance' });
      }
      return;
    }

    // Brothel girls – quest turn‑in or main interaction
    const girlIds = ['lilia', 'nera', 'velena'];
    if (girlIds.includes(obj.id)) {
      // 1) Check if an active quest requires talking to this girl (turn‑in)
      const questId = `brothel_${obj.id}_quest`;
      const quest = state.quests[questId];
      if (quest && quest.status === 'active') {
        const idx = quest.currentObjectiveIndex ?? 0;
        const objective = QUESTS[questId]?.objectives?.[idx];
        if (objective && objective.type === 'talk' && objective.target === obj.id) {
          dispatch({ type: 'SET_DIALOGUE', payload: `${obj.id}_turnin` });
          return;
        }
      }

      // 2) Normal interaction
      if (!state.brothelUnlocked.includes(obj.id)) {
        dispatch({ type: 'SET_DIALOGUE', payload: `${obj.id}_quest_start` });
      } else {
        dispatch({ type: 'SET_DIALOGUE', payload: `${obj.id}_interact` });
      }
      return;
    }

    // Guild receptionist quest turn‑ins
    if (obj.id === 'receptionist') {
      const herbQuest = state.quests['side_herb_collection'];
      if (herbQuest?.status === 'active' && herbQuest.currentObjectiveIndex === 1 && herbQuest.objectives[1].type === 'talk') {
        dispatch({ type: 'SET_DIALOGUE', payload: 'herb_turnin' });
        return;
      }
      const slimeQuest = state.quests['side_slime_hunt'];
      if (slimeQuest?.status === 'active' && slimeQuest.currentObjectiveIndex === 1 && slimeQuest.objectives[1].type === 'talk') {
        dispatch({ type: 'SET_DIALOGUE', payload: 'slime_turnin' });
        return;
      }
      const trollQuest = state.quests['side_troll_hunt'];
      if (trollQuest?.status === 'active' && trollQuest.currentObjectiveIndex === 1 && trollQuest.objectives[1].type === 'talk') {
        dispatch({ type: 'SET_DIALOGUE', payload: 'troll_turnin' });
        return;
      }
    }

    if (obj.id === 'recruitment_lounge') {
      dispatch({ type: 'SET_GAME_MODE', payload: 'recruitment' });
      return;
    }

    // Map transition
    if (obj.transitionMap) {
      dispatch({ type: 'ADVANCE_TIME', payload: 30 });
      dispatch({ type: 'SET_MAP', payload: obj.transitionMap });
      const nextMap = MAPS[obj.transitionMap];
      const spawnPos = obj.targetPosition || nextMap.playerStart;
      dispatch({ type: 'SET_POSITION', payload: { ...spawnPos } });
      if (obj.dialogueId) dispatch({ type: 'SET_DIALOGUE', payload: obj.dialogueId });
      else dispatch({ type: 'SET_GAME_MODE', payload: 'map' });
    } else if (obj.dialogueId) {
      dispatch({ type: 'SET_DIALOGUE', payload: obj.dialogueId });
    } else if (obj.triggerBattle) {
      startBattle(obj.triggerBattle);
    }
  }, [dispatch, startBattle, state, showBedMenu, ambushBanner]);

  // Bed actions
  const isNight = state.hour >= 20 || state.hour < 6;
  const handleSleep = () => {
    setShowBedMenu(false);
    dispatch({ type: 'APPLY_EFFECTS', payload: { fullHeal: true, sleep: true } });

    if (state.goddessRealmUnlocked) return;

    if (state.goddessDreamPhase === 'invited') {
      dispatch({ type: 'SET_DIALOGUE', payload: 'goddess_invite_entry' });
      return;
    }

    const affection = state.affection['goddess'] || 0;
    const chance = Math.min(0.5, affection / 120);
    if (Math.random() < chance) {
      dispatch({ type: 'SET_DIALOGUE', payload: 'goddess_dream_entry' });
    }
  };
  const handleRest = () => {
    setShowBedMenu(false);

    if (!state.goddessRealmUnlocked && state.goddessDreamPhase !== 'invited') {
      const affection = state.affection['goddess'] || 0;
      const chance = Math.min(0.5, affection / 120);
      if (Math.random() < chance) {
        dispatch({ type: 'APPLY_EFFECTS', payload: { fullHeal: true, restHours: 2 } });
        setTimeout(() => {
          dispatch({ type: 'SET_MAP', payload: 'realm' });
          const realmMap = MAPS['realm'];
          dispatch({ type: 'SET_POSITION', payload: { ...realmMap.playerStart } });
          dispatch({ type: 'SET_GAME_MODE', payload: 'map' });
          dispatch({ type: 'APPLY_EFFECTS', payload: { setInDreamVisit: true } });
        }, 100);
        return;
      }
    }

    dispatch({ type: 'APPLY_EFFECTS', payload: { fullHeal: true, restHours: 2 } });
  };
  const handleGoToRealm = () => {
    setShowBedMenu(false);
    dispatch({ type: 'SET_MAP', payload: 'realm' });
    const realmMap = MAPS['realm'];
    dispatch({ type: 'SET_POSITION', payload: { ...realmMap.playerStart } });
    dispatch({ type: 'SET_GAME_MODE', payload: 'map' });
  };

  const isTrackedQuestRelated = (obj) => {
    if (!state.trackedQuestId || !obj.questRelated) return false;
    const quest = state.quests[state.trackedQuestId];
    if (!quest || quest.status !== 'active') return false;
    return obj.questRelated.includes(state.trackedQuestId);
  };

  if (!mapData) return <div>Map not found: {state.currentMap}</div>;

  const visibleInteractables = (mapData.interactables || []).filter(obj => {
    if (obj.type === 'item' && state.collectedItems.includes(obj.id)) return false;
    return true;
  });

  return (
    <div
      className="map-view"
      style={{
        width: '100%',
        height: '100%',
        background: mapData.background,
        position: 'relative',
        overflow: 'hidden',
        cursor: ambushBanner ? 'default' : 'crosshair',
      }}
      onClick={handleMapClick}
    >
      {/* Interactable objects */}
      {visibleInteractables.map(obj => (
        <div
          key={obj.id}
          className={`interactable ${nearInteractable?.id === obj.id ? 'highlight' : ''}`}
          style={{
            position: 'absolute',
            left: obj.x - obj.width / 2,
            top: obj.y - obj.height / 2,
            width: obj.width,
            height: obj.height,
            fontSize: obj.type === 'door' ? '36px' : '30px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
          onClick={(e) => {
            e.stopPropagation();
            if (nearInteractable?.id === obj.id) handleInteraction(obj);
            else setTargetPos({ x: obj.x, y: obj.y });
          }}
        >
          <span style={{ pointerEvents: 'none' }}>{obj.icon}</span>
          {isTrackedQuestRelated(obj) && (
            <span style={{
              position: 'absolute',
              top: -10,
              right: -10,
              fontSize: 18,
              color: '#ffd700',
              filter: 'drop-shadow(0 0 4px gold)',
            }}>
              ❗
            </span>
          )}
        </div>
      ))}

      {/* Player */}
      <div
        className={`player ${encounterExclamation ? 'shake' : ''}`}
        style={{
          position: 'absolute',
          left: state.playerPosition.x - 15,
          top: state.playerPosition.y - 18,
          fontSize: '32px',
          filter: 'drop-shadow(0 2px 4px rgba(0,0,0,0.5))',
          zIndex: 10,
          pointerEvents: 'none',
        }}
      >
        🧑
        {encounterExclamation && (
          <span style={{ position: 'absolute', right: -24, top: -10, fontSize: 24 }}>❗</span>
        )}
      </div>

      {/* Interaction prompt */}
      {nearInteractable && !ambushBanner && (
        <div
          className="interact-prompt"
          style={{
            position: 'absolute',
            left: state.playerPosition.x - 60,
            top: state.playerPosition.y - 55,
            background: 'rgba(0,0,0,0.85)',
            color: '#ffd700',
            padding: '4px 12px',
            borderRadius: '12px',
            fontSize: '13px',
            pointerEvents: 'none',
            zIndex: 20,
            whiteSpace: 'nowrap',
            animation: 'pulse 1.5s infinite',
          }}
        >
          [Click] {nearInteractable.name}
        </div>
      )}

      {/* Click target indicator */}
      {targetPos && !ambushBanner && (
        <div
          style={{
            position: 'absolute',
            left: targetPos.x - 8,
            top: targetPos.y - 8,
            width: 16,
            height: 16,
            borderRadius: '50%',
            border: '2px solid rgba(255,215,0,0.8)',
            pointerEvents: 'none',
            zIndex: 15,
          }}
        />
      )}

      {/* Encounter flash */}
      {encounterFlash && <div className="encounter-flash" />}

      {/* Monster Ambush Banner */}
      {ambushBanner && (
        <div
          style={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            background: 'rgba(0,0,0,0.85)',
            border: '3px solid #ff4444',
            borderRadius: 16,
            padding: '20px 40px',
            color: '#ff4444',
            fontSize: '36px',
            fontWeight: 'bold',
            textAlign: 'center',
            zIndex: 60,
            animation: 'ambushPulse 0.6s infinite alternate',
          }}
        >
          ⚔️ MONSTER AMBUSH! ⚔️
        </div>
      )}

      {/* Top HUD */}
      <div className="map-hud">
        💰 {state.gold}g | 🗺️ {mapData.name} | 🕒 Day {state.day} {String(state.hour).padStart(2, '0')}:00
      </div>
      <button
        className="menu-button"
        onClick={(e) => {
          e.stopPropagation();
          dispatch({ type: 'TOGGLE_MENU' });
        }}
      >
        📋 Menu
      </button>

      {/* Quest popup */}
      {state.mapQuestPopup && (
        <div
          style={{
            position: 'absolute',
            top: 50,
            left: 8,
            background: 'rgba(10,10,20,0.95)',
            border: '2px solid #ffd700',
            borderRadius: 8,
            padding: '10px 16px',
            color: '#fff',
            zIndex: 50,
            maxWidth: 220,
            animation: 'fadeIn 0.3s',
          }}
        >
          <div style={{ fontWeight: 'bold', color: '#ffd700', marginBottom: 4 }}>📜 New Quest!</div>
          <div style={{ fontSize: 13, marginBottom: 4 }}>{state.mapQuestPopup.name}</div>
          <div style={{ fontSize: 11, color: '#ccc', marginBottom: 8 }}>{state.mapQuestPopup.objectiveText}</div>
          <button onClick={() => {
            dispatch({ type: 'OPEN_MENU_WITH_TAB', payload: 'quests' });
            dispatch({ type: 'SET_TRACKED_QUEST', payload: state.mapQuestPopup.questId });
            dispatch({ type: 'CLEAR_MAP_QUEST_POPUP' });
          }} style={{
            background: 'none',
            border: '1px solid #ffd700',
            color: '#ffd700',
            padding: '4px 8px',
            borderRadius: 4,
            cursor: 'pointer',
            fontSize: 11,
          }}>
            View Details
          </button>
        </div>
      )}

      {/* Tracked quest indicator */}
      {state.trackedQuestId && state.quests[state.trackedQuestId]?.status === 'active' && (
        <div style={{
          position: 'absolute',
          top: 50,
          left: 8,
          background: 'rgba(0,0,0,0.8)',
          color: '#ffd700',
          padding: '6px 12px',
          borderRadius: 8,
          fontSize: 12,
          zIndex: 30,
          maxWidth: 200,
          border: '1px solid rgba(255,215,0,0.5)',
          lineHeight: 1.4,
        }}>
          <div style={{ fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: 4 }}>
            <span>❗</span> {QUESTS[state.trackedQuestId].name}
          </div>
          {(() => {
            const quest = state.quests[state.trackedQuestId];
            const idx = quest.currentObjectiveIndex ?? 0;
            const obj = QUESTS[state.trackedQuestId].objectives?.[idx];
            if (!obj) return null;
            let current = 0;
            const prog = quest.objectiveProgress?.[obj.id];
            if (obj.type === 'collect' || obj.type === 'defeat') {
              current = prog?.currentCount || 0;
            } else if (obj.type === 'visit') {
              current = state.visitedLocations.includes(obj.target) ? 1 : 0;
            } else if (obj.type === 'talk') {
              current = prog?.currentCount || 0;
            }
            return (
              <div style={{ color: '#ccc', paddingLeft: 8 }}>
                • {obj.type === 'collect' ? '🌿' : obj.type === 'defeat' ? '⚔️' : '📍'} {obj.type === 'collect' ? 'Collect' : obj.type === 'defeat' ? 'Defeat' : 'Visit'} {obj.target}: {current}/{obj.count}
              </div>
            );
          })()}
        </div>
      )}

      {/* Quest NPCs */}
      {state.quests && Object.values(state.quests).filter(q => q.status === 'active').map(quest => {
        const obj = quest.objectives?.[quest.currentObjectiveIndex || 0];
        if (!obj || obj.type !== 'talk') return null;
        const npcId = obj.target;
        const npc = MAPS[state.currentMap]?.questNPCs?.[npcId];
        if (!npc) return null;
        return (
          <div
            key={npcId}
            className={`interactable ${nearInteractable?.id === npcId ? 'highlight' : ''}`}
            style={{
              position: 'absolute',
              left: npc.x - 20,
              top: npc.y - 30,
              width: 40,
              height: 60,
              fontSize: 30,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
            onClick={(e) => {
              e.stopPropagation();
              if (nearInteractable?.id === npcId) {
                dispatch({ type: 'SET_DIALOGUE', payload: npc.dialogueId || `${npcId}_default` });
              } else {
                setTargetPos({ x: npc.x, y: npc.y });
              }
            }}
          >
            <span style={{ pointerEvents: 'none' }}>{npc.icon}</span>
          </div>
        );
      })}

      {/* Bed Menu Overlay */}
      {showBedMenu && (
        <div style={{
          position: 'absolute',
          inset: 0,
          background: 'rgba(0,0,0,0.85)',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 200,
          gap: 20,
        }}>
          {isNight ? (
            <button onClick={handleSleep} style={{
              padding: '16px 40px',
              fontSize: 20,
              background: '#2a2a3a',
              color: '#ffd700',
              border: '2px solid #ffd700',
              borderRadius: 12,
              cursor: 'pointer',
            }}>
              🛏️ Sleep until morning
            </button>
          ) : (
            <button onClick={handleRest} style={{
              padding: '16px 40px',
              fontSize: 20,
              background: '#2a2a3a',
              color: '#ffd700',
              border: '2px solid #ffd700',
              borderRadius: 12,
              cursor: 'pointer',
            }}>
              🛏️ Rest (2 hours)
            </button>
          )}
          {state.goddessRealmUnlocked && (
            <button onClick={handleGoToRealm} style={{
              padding: '16px 40px',
              fontSize: 20,
              background: '#3a2a5a',
              color: '#e0d0ff',
              border: '2px solid #b7a1e0',
              borderRadius: 12,
              cursor: 'pointer',
            }}>
              ✨ Go to Celestial Realm
            </button>
          )}
          <button onClick={() => setShowBedMenu(false)} style={{
            padding: '10px 24px',
            fontSize: 16,
            background: '#555',
            color: '#fff',
            border: 'none',
            borderRadius: 8,
            cursor: 'pointer',
          }}>
            Cancel
          </button>
        </div>
      )}

      <div className="controls-hint-map">🖱️ Click to move | Click objects to interact</div>
    </div>
  );
}