import React from 'react';
import { useGame } from '../context/GameContext';
import { ITEMS } from '../data';

const FAVORITE_MAP = {
  lilia: 'ruby_earring',
  nera: 'silver_ring',
  velena: 'gold_necklace',
};

export default function GiftView() {
  const { state, dispatch } = useGame();
  const target = state.giftTarget; // girl id
  const giftItems = Object.entries(state.inventory)
    .filter(([id, count]) => count > 0 && ITEMS[id]?.type === 'gift')
    .map(([id, count]) => ({ id, count, item: ITEMS[id] }));

  const handleSelect = (itemId) => {
    const item = ITEMS[itemId];
    if (!item) return;
    dispatch({ type: 'REMOVE_ITEM', payload: itemId });
    if (target && item.effect?.affection) {
      let amount = item.effect.affection;
      if (FAVORITE_MAP[target] === itemId) {
        amount *= 2; // double for her favorite
      }
      dispatch({ type: 'SET_AFFECTION', payload: { charId: target, amount } });
    }
    dispatch({ type: 'END_GIFT' });
  };

  return (
    <div style={{
      width: '100%', height: '100%', background: 'rgba(0,0,0,0.9)',
      display: 'flex', flexDirection: 'column', alignItems: 'center',
      justifyContent: 'center', color: '#fff'
    }}>
      <h2>🎁 Choose a gift</h2>
      {giftItems.length === 0 && <p>No gift items in inventory.</p>}
      {giftItems.map(gi => (
        <button key={gi.id} onClick={() => handleSelect(gi.id)} style={{
          margin: 5, padding: '10px 20px', background: '#333',
          color: '#ffd700', border: '1px solid #ffd700', borderRadius: 8,
          cursor: 'pointer'
        }}>
          {gi.item.name} (x{gi.count}) – +{gi.item.effect.affection} affection
          {FAVORITE_MAP[target] === gi.id ? ' (favorite!)' : ''}
        </button>
      ))}
      <button onClick={() => dispatch({ type: 'END_GIFT' })} style={{
        marginTop: 20, padding: '10px 20px', background: '#555',
        color: '#fff', border: 'none', borderRadius: 8, cursor: 'pointer'
      }}>Back</button>
    </div>
  );
}